class SegmentTree
  @n : (Int64|Int32)
  @log : (Int64|Int32)
  @leaf_size : (Int64|Int32)
  @d : Array(Int64)
  @e : Int64

  def initialize(a, form)

    @e  = 0_i64
    @op = Proc(Int64, Int64, Int64).new{ |x, y| x + y }

    case form.to_s
    when "gcd"
      @e  = 0_i64
      @op = Proc(Int64, Int64, Int64).new { |x, y| x.gcd y }
    when "max"
      @e  = -(1_i64 << 60) + 1
      @op = Proc(Int64, Int64, Int64).new { |x, y| {x, y}.max }
    when "min"
      @e  = (1_i64 << 60) - 1
      @op = Proc(Int64, Int64, Int64).new { |x, y| {x, y}.min }
    when "or"
      @e  =  0_i64
      @op = Proc(Int64, Int64, Int64).new{ |x, y| x | y }
    when "sum"
      @e  =  0_i64
      @op = Proc(Int64, Int64, Int64).new{ |x, y| x + y }
    end

    @n = a.size
    @log = ceil_pow2(@n)
    @leaf_size = 1 << @log
    @d = Array.new(@leaf_size * 2) { @e }
    a.each_with_index { |a_i, i| @d[@leaf_size + i] = a_i }
    (@leaf_size - 1).downto(1) { |i| update(i) }
    self
  end

  def set(q, x)
    q += @leaf_size
    @d[q] = x
    1.upto(@log) { |i| update(q >> i) }
  end

  def get(q)
    d[leaf_size + q]
  end

  def prod(l, r)
    sml = @e
    smr = @e
    l += @leaf_size
    r += @leaf_size

    while l < r
      if l.bit(0) == 1
        sml = @op.call(sml, @d[l])
        l += 1
      end
      if r.bit(0) == 1
        r -= 1
        smr = @op.call(@d[r], smr)
      end
      l //= 2
      r //= 2
    end

    @op.call(sml, smr)
  end

  def all_prod
    d[1]
  end

  def max_right(l, v)
    return @n if l == @n

    f = Proc(Int64, Bool).new { |x| x < v }

    l += @leaf_size
    sm = @e
    loop do
      while l.even?
        l //= 2
      end 
      unless f.call(@op.call(sm, @d[l]))
        while l < @leaf_size
          l *= 2
          if f.call(@op.call(sm, @d[l]))
            sm = @op.call(sm, @d[l])
            l += 1
          end
        end
        return l - @leaf_size
      end
      sm = @op.call(sm, @d[l])
      l += 1
      break if (l & -l) == l
    end

    @n
  end

  private def update(k)
    @d[k] = @op.call(@d[2 * k], @d[2 * k + 1])
  end

  private def inspect
    t = 0
    res = "SegmentTree\n  "
    a = @d[1, @d.size - 1]
    a.each_with_index do |e, i|

      res << e.to_s << " "
      if t == i && i < @leaf_size
        res << "\n  "
        t = t * 2 + 2
      end
    end
    res
  end
end

