namespace cplib {
	template<class Monoid> class segment_tree {
	public:
		using value_type = Monoid;
		using usize = std::uint_fast32_t;

	private:
		std::vector<value_type> data;

	public:
		segment_tree() = default;
		explicit segment_tree(usize n): data(2 * n, value_type::identity) {}
		explicit segment_tree(const std::vector<value_type>& vec): segment_tree(2 * vec.size()) {
			for(usize i = 0; i < vec.size(); i++) set(i, vec[i]);
			build();
		}

		usize size() const { return data.size() >> 1; }
		value_type get(usize i) const { return data[i + size()]; }
		void set(usize i, const value_type& x) { data[i + size()] = x; }

		void build() {
			for(usize i = size() - 1; i > 0; i--)
				data[i] = value_type::operation(data[i * 2 + 0], data[i * 2 + 1]);
		}
		void change(usize i, const value_type& x) {
			data[i += size()] = x;
			while(i >>= 1) data[i] = value_type::operation(data[i * 2 + 0], data[i * 2 + 1]);
		}
		void update(usize i, const value_type& x) { change(i, value_type::operation(get(i), x)); }

		value_type fold(usize first, usize last) const {
			first += size();
			last += size();

			value_type lval = value_type::identity;
			value_type rval = value_type::identity;
			while(first != last) {
				if(first & 1) lval = value_type::operation(lval, data[first++]);
				if(last  & 1) rval = value_type::operation(data[--last], rval);
				first >>= 1;
				last  >>= 1;
			}
			return value_type::operation(lval, rval);
		}
		value_type fold_all() const { return data[1]; }

		// return max{r | f(fold(l, r - 1)) = true}
		template<class F> usize search_right(usize l, const F& f) const {
			if(l == size()) return size();

			l += size();
			value_type acc = value_type::identity;
			do {
				while(l % 2 == 0) l >>= 1;
				if(!f(value_type::operation(acc, data[l]))) {
					while(l < size()) {
						l = l << 1;
						if(f(value_type::operation(acc, data[l]))) {
							acc = value_type::operation(acc, data[l]);
							l += 1;
						}
					}
					return l - size();
				}
				acc = value_type::operation(acc, data[l]);
				l += 1;
			} while((l & -l) != l);
			return size();
		}

		// return min{l | f(fold(l, r - 1) = true}
		template<class F> usize search_left(usize r, const F& f) const {
			if(r == 0) return 0;

			r += size();
			value_type acc = value_type::identity;
			do {
				r--;
				while(r > 1 and (r % 2)) r >>= 1;
				if(!f(value_type::operation(data[r], acc))) {
					while(r < size()) {
						r = r * 2 + 1;
						if(f(value_type::operation(data[r], acc))) {
							acc = value_type::operation(data[r], acc);
							r -= 1;
						}
					}
					return r + 1 - size();
				}
				acc = value_type::operation(data[r], acc);
			} while((r & -r) == r);
			return 0;
		}
	};

	template<class T, T id = T{}>
	struct add_monoid {
		T a;

		static constexpr add_monoid operation(const add_monoid& l, const add_monoid& r) { return add_monoid{l.a + r.a}; }
		static constexpr add_monoid identity{id};
	};

	template<class T, T id = T{1}>
	struct mul_monoid {
		T a;

		static constexpr mul_monoid operation(const mul_monoid& l, const mul_monoid& r) { return mul_monoid{l.a * r.a}; }
		static constexpr mul_monoid identity{id};
	};

	template<class T, T id = T{}>
	struct max_monoid {
		T a;

		static constexpr max_monoid operation(const max_monoid& l, const max_monoid& r) { return max_monoid{std::max(l.a, r.a)}; }
		static constexpr max_monoid identity{id};
	};

	template<class T, T id = T{}>
	struct min_monoid {
		T a;

		static constexpr min_monoid operation(const min_monoid& l, const min_monoid& r) { return min_monoid{std::min(l.a, r.a)}; }
		static constexpr min_monoid identity{id};
	};
}

