template <typename Monoid>
struct SegmentTree {
public:
    using Type = typename Monoid::Type;
    int sz; // Array size
    int _n;
    vector<Type>node;
    SegmentTree(int n):_n(n){
        sz = 1;
        while(sz < n) sz <<= 1;
        node.assign(2*sz,Monoid::id());
    }
    void set(int k,const Type& val){
        node[k+sz] = val;
    }
    void build(){
        for(int k = sz - 1; k > 0; k--){
            node[k] = Monoid::op(node[2*k],node[2*k+1]);
        }
    }
    inline void update(int k, const Type& val) {
        k += sz;
        node[k] = val;
        while (k >>= 1) {
            node[k] = Monoid::op(node[2*k], node[2*k+1]);
        }
    }
    inline Type query(int l, int r) {
        if (l >= r)return Monoid::id();
        Type vl = Monoid::id(), vr = Monoid::id();
        for (l += sz, r += sz; l != r; l >>= 1, r >>= 1) {
            if (l & 1)  vl = Monoid::op(vl, node[l++]);
            if (r & 1)  vr = Monoid::op(node[--r], vr);
        }
        return Monoid::op(vl, vr);
    }


    template <bool (*f)(Type)> int max_right(int l) {
        return max_right(l, [](Type x) { return f(x); });
    }
    template <class F> int max_right(int l, F f) {
        assert(0 <= l && l <= _n);
        assert(f(Monoid::id()));
        if (l == _n) return _n;
        l += sz;
        Type sm = Monoid::id();
        do {
            while (l % 2 == 0) l >>= 1;
            if (!f(op(sm, node[l]))) {
                while (l < sz) {
                    l = (2 * l);
                    if (f(op(sm, node[l]))) {
                        sm = op(sm, node[l]);
                        l++;
                    }
                }
                return l - sz;
            }
            sm = op(sm, node[l]);
            l++;
        } while ((l & -l) != l);
        return _n;
    }

    template <bool (*f)(Type)> int min_left(int r) {
        return min_left(r, [](Type x) { return f(x); });
    }
    template <class F> int min_left(int r, F f) {
        assert(0 <= r && r <= _n);
        assert(f(Monoid::id()));
        if (r == 0) return 0;
        r += sz;
        Type sm = Monoid::id();
        do {
            r--;
            while (r > 1 && (r % 2)) r >>= 1;
            if (!f(op(node[r], sm))) {
                while (r < sz) {
                    r = (2 * r + 1);
                    if (f(op(node[r], sm))) {
                        sm = op(node[r], sm);
                        r--;
                    }
                }
                return r + 1 - sz;
            }
            sm = op(node[r], sm);
        } while ((r & -r) != r);
        return 0;
    }

    Type operator[](int i) { return node[i + sz]; }
};

struct Monoid {
    using Type = ll;/* Monoidに乗せる型 */
    static Type id() { return 0; /* モノイドの初期値 */};

    // ================================================ //
    //          マージ処理                               //
    // ================================================ //
    static Type op(const Type&l, const Type &r) {
        Type ret = max(l,r);
        return ret;
    }
};
template<class Type>
Type solve(Type res = Type()){
    int N,Q; cin >> N >> Q;

    SegmentTree<Monoid> ST(N);
    for(int i = 0; i < N;i++){
        int A; cin >> A;
        ST.set(i,A);
    }
    ST.build();

    while(Q--){
        int T; cin >> T;
        if(T == 1){
            int X,V; cin >> X >> V;
            ST.update(X-1,V);
        }else if(T == 2){
            int L,R; cin >> L >> R;
            cout << ST.query(L-1,R) << endl;
        }else{
            int X,V; cin >> X >> V;
            cout << ST.max_right(X-1,[V](Monoid::Type x){
                return V < x;
            });
        }
    }
    return res;
}
int main(void) {
    cin.tie(0); ios::sync_with_stdio(false);
    solve<ll>(0);
    // cout << fixed << setprecision(12) << solve<ll>() << endl;
    return 0;
}

