struct segtree{
  ll M=1, INIT;
  vector<ll> dat;
  segtree(ll N, ll num):INIT(num){
    while(M<N) M*=2;
    dat.resize(M*2-1, num);
  }
  void update(ll x, ll k){
    k+=M-1;
    dat[k] = x;
    while(k>0) k = (k-1)/2, dat[k] = max(dat[k*2+1],dat[k*2+2]);
  }
  ll query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return INIT;
    if(a<=l && r<=b) return dat[k];
    ll A = query(a, b, k*2+1, l, (l+r)/2);
    ll B = query(a, b, k*2+2, (l+r)/2, r);
    return max(A, B);
  }
};


/*
R-Lが2べき(M)、条件文が
L <-ng-----------ok> R
である必要がある

if_flip
false: query(0, mid)
true : query(mid, n)

bisearch(merge_func, 条件式)
条件を満たす最小のidxを返す

*/

template<class segmenttree, typename T, T zero>
struct SegBisearchManip{
  segmenttree& seg;
  ll M, l, r;
  T ok_data, false_data, tmp_data;
  bool is_flip;
  SegBisearchManip(segmenttree& s, bool flip = false):seg(s), is_flip(flip){
    M = seg.M * 2 - 1;//size = 2M - 1
    init();
  }
  void init(){
    l = 1, r = 2;
    ok_data = zero;
    false_data = zero;
  }
  template<typename F>
  T check(F& f){
    if(max(l, r)>=M){
      std::cout << l << " " << r << " " << M << '\n';
      std::cout << "error" << '\n';
      return zero;
    }
    return tmp_data = f(seg.dat[(is_flip?r:l)], (is_flip?ok_data:false_data));
  }
  void is_ok(){
    ok_data = tmp_data;
    if(!is_flip){
      r = l*2+2;
      l = l*2+1;
    }else{
      l = r*2+1;
      r = r*2+2;
    }
  }
  void is_ng(){
    false_data = tmp_data;
    if(is_flip){
      r = l*2+2;
      l = l*2+1;
    }else{
      l = r*2+1;
      r = r*2+2;
    }
  }
  template<typename F, typename G>
  ll bisearch(const F& f, const G& g){
    init();
    ll L = 0, R = (M+1)/2;
    while(R-L>1){
      ll mid = (L+R)/2;
      ll t = check(f);
      if(g(t, mid)){
        R = mid;
        is_ok();
      }else{
        L = mid;
        is_ng();
      }
    }
    return R-1;
  }
};

int main(){
  ll n, q;scanf("%lld %lld", &n, &q);
  segtree seg(n, -10000000000);
  for(int i=0;i<n;i++){
    ll a;scanf("%lld", &a);
    seg.update(a, i);
  }
  SegBisearchManip<segtree, ll, -10000000000> sm(seg, false);
  for(int i=0;i<q;i++){
    ll a, b, c;scanf("%lld %lld %lld", &a, &b, &c);
    b--;
    if(a==1){
      seg.update(c, b);
    }else if(a==2){
      ll ans = seg.query(b, c);
      printf("%lld\n", ans);
    }else{
      ll ans = sm.bisearch(
        [&](ll x, ll y){return max(x, y);},
        [&](ll x, ll idx){
          if(idx<b) return false;
          if(x>=c) return true;
          return false;
        }
      );
      printf("%lld\n", min(ans+1, n+1));
    }
  }
  return 0;
}

