signed main() {
	INIT;

	VAR(int, n, Q);
	VEC(int, a, n);

	a.emplace_back(INFINT);
	SegmentTree<Monoid::max<int>> st(a);
	REP(_, Q) {
		VAR(int, t, l, r);
		if (t == 1) {
			st.update(--l, r);
		}
		else if (t == 2) {
			OUT(st.query(--l, r))BR;
		}
		else {
			OUT(st.max_right(--l, [r](int x) {return x >= r; }) + 1)BR;
		}
	}

	return 0;
}

