    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0;i < n;++i) cin >> a[i];
    SegmentTree seg(a);
    for (int i = 0;i < q;++i) {
        int t,x,v;
        cin >> t >> x >> v;
        if (t == 1) seg.update(x-1,v);
        else if (t == 2) cout << seg.getmax(x-1,v) << newl;
        else cout << seg.find(x-1,n,v-1)+1 << newl;
    }
}

