template <typename X>
struct SegTree {
  using FX = function<X(X, X)>;
  int n;
  FX fx;
  const X ex;
  vector<X> dat;
  SegTree(int n_, FX fx_, X ex_) : n(), fx(fx_), ex(ex_), dat(n_ * 4, ex_) {
    int x = 1;
    while (n_ > x) {
      x *= 2;
    }
    n = x;
  }

  void set(int i, X x) { dat[i + n - 1] = x; }
  void build() {
    for (int k = n - 2; k >= 0; k--) {
      dat[k] = fx(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  void update(int i, X x) {
    i += n - 1;
    dat[i] = x;
    while (i > 0) {
      i = (i - 1) / 2;
      dat[i] = fx(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
  }

  X query(int a, int b) { return query_sub(a, b, 0, 0, n); }
  X query_sub(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return ex;
    } else if (a <= l || r <= b) {
      return dat[k];
    } else {
      X vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
      X vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
      return fx(vl, vr);
    }
  }

  int find_leftest(int a, int b, X x) { return find_leftest_sub(a, b, x, 0, 0, n); }
  int find_leftest_sub(int a, int b, X x, int k, int l, int r) {
    if (dat[k] < x || r <= a || b <= l) {
      return b;
    } else if (k >= n - 1) {
      return (k - (n - 1));
    } else {
      int vl = find_leftest_sub(a, b, x, 2 * k + 1, l, (l + r) / 2);
      if (vl != b) {
        return vl;
      } else {
        return find_leftest_sub(a, b, x, 2 * k + 2, (l + r) / 2, r);
      }
    }
  }
};

int main() {
  int n,q;
  cin >> n >> q;
  auto fx = [](int x1, int x2) -> int { return max(x1, x2); };
  int ex = -1;
  SegTree<int> rmq(n, fx, ex);
  rep(i,0,n) {
    int a;
    cin >> a;
    rmq.set(i+1, a);
  }
  rmq.build();

  rep(i,0,q) {
    int t, a, b;
    cin >> t >> a >> b;
    if (t == 1) {
      rmq.update(a, b);
    } else if (t == 2) {
      cout << rmq.query(a, b+1) << endl;
    } else {
      int k = rmq.find_leftest(a, n, b);
      if (k == n) {
        int p = rmq.query(n,n);
        if (b > p) {
          cout << n + 1 << endl;
        } else {
          cout << n << endl;
        }
      }
    }
  }
  return 0;
}

