        int q, a, b; cin >> q >> a >> b; a--;
        if(q == 1) seg.change(a, b);
        if(q == 2) cout << seg.query(a, b) << endl;
        if(q == 3){
            int ans = seg.find_first(a, b);
            cout << (ans == -1? N+1 : ans+1) << endl;
        }
    }
}

