using namespace std;

struct segtree{
  ll M=1, INIT;
  vector<ll> dat;
  segtree(ll N, ll num):INIT(num){
    while(M<N) M*=2;
    dat.resize(M*2-1, num);
  }
  void update(ll x, ll k){
    k+=M-1;
    dat[k] = x;
    while(k>0) k = (k-1)/2, dat[k] = max(dat[k*2+1],dat[k*2+2]);
  }
  ll query(ll a, ll b=-1, ll k=0, ll l=0, ll r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return INIT;
    if(a<=l && r<=b) return dat[k];
    ll A = query(a, b, k*2+1, l, (l+r)/2);
    ll B = query(a, b, k*2+2, (l+r)/2, r);
    return max(A, B);
  }
};


int main(){
  ll INF = 10000000000;
  ll n, q;scanf("%lld %lld", &n, &q);
  segtree seg(n, -INF);
  for(int i=0;i<n;i++){
    ll a;scanf("%lld", &a);
    seg.update(a, i);
  }
  for(int i=0;i<q;i++){
    ll t, a, b;scanf("%lld %lld %lld", &t, &a, &b);
    a--;
    if(t==1){
      seg.update(b, a);
    }else if(t==2){
      printf("%lld\n", seg.query(a, b));
    }else{
      if(seg.query(a, n)<b){
        printf("%lld\n", n+1);
        continue;
      }
      //a~n-1
      ll l = a, r = n;//:l:ある
      while(r-l>1){
        ll mid = (l + r)/2;
        if(seg.query(mid, n)<b) r = mid;
        else l = mid;
      }
      printf("%lld\n", l+1);
    }
  }
}

