/*
    Range Queries is O(log n)
    ex sum/max/min of a[l...r]
    a[l..r] -> (a[l...m-1],a[m...r])k
*/

#include <iostream>
#include <vector>
#include <math.h>

struct SegmentTree{
public:
    const static int MAX= 200001;
    int n, Tmax[MAX*4], T[MAX];
    SegmentTree(int N, std::vector<int> A){
        n=N;
        for(int i=0; i<n;++i){
            T[i]=A[i];
        }
    }
    void build_tree(std::vector<int> A, int v, int tl, int tr){
        if(tl==tr){
            Tmax[v]=A[tl];
            return;
        }
        int mid=  (tl+tr)/2;
        // root at index i has children left at 2i and right at 2i+1.
        build_tree(A,2*v,tl,mid);
        build_tree(A,2*v+1,mid+1,tr);
        Tmax[v]= std::max(Tmax[2*v],Tmax[2*v+1]);
    }

    int max_tree(int v,int tl, int tr, int l, int r){
        if(l>r){
            return 0;
        }
        if(tl==l && tr==r){
            return Tmax[v];
        }
        int tm= (tl+tr)/2;
        return std::max(max_tree(v*2,tl,tm,l,std::min(r,tm))
                , max_tree(v*2+1,tm+1,tr,std::max(l,tm+1),r));;
    }

    int min_tree(int left,int a){
        for(int i=left; i<n;++i){
            if(T[i]>=a){
                return i+1;
            }
        }
        return n+1;
    }
    void update_tree(int v, int tl, int tr, int pos, int val){
        T[pos]=val;
        if(tl==tr){
            Tmax[v]=val;
            return;
        }
        int mid=  (tl+tr)/2;
        if(pos<=mid){
            update_tree(2*v,tl,mid,pos,val);
        }else{
            update_tree(2*v+1,mid+1,tr,pos,val);
        }
        Tmax[v]= std::max(Tmax[2*v],Tmax[2*v+1]);
    }
};

int main(){
    int n,q;
    cin>>n>>q;
    vector<int> A;
    for(int i=0; i<n; ++i){
        int a; 
        cin>>a;
        A.push_back(a);
    }
    SegmentTree st= SegmentTree(n,A);
    st.build_tree(A,1,0,n-1);

    for(int i=0; i<q; ++i){
        int t,l,r;
        cin>>t>>l>>r;
        l--;r--;

        if(t==1){
            r++;
            st.update_tree(1,0,n-1,l,r);
        }else if(t==2){
            cout<<st.max_tree(1,0,n-1,l,r)<<endl;
        }else{
            r++;
            cout<<st.min_tree(l,r)<<endl;
        }
    }

    return 0;
}

