    ll n,q;cin>>n>>q;
    SegmentTree<ll> seg(n,[](ll a,ll b){return max(a,b);},-INF);
    rep(i,n){
        ll a;cin>>a;
        seg.set(i,a);
    }
    seg.build();
	while(q--){
        ll t;cin>>t;
        if(t==1){
            ll x,v;cin>>x>>v;
			x--;
			seg.update(x,v);
        }else if(t==2){
            ll l,r;cin>>l>>r;
			l--;
            ll ans=seg.query(l,r);
            cout<<ans<<endl;
        }else{
            ll x,v;cin>>x>>v;
			x--;
            ll d=seg.query(x,n);
            if(v>d){
                cout<<n+1<<endl;
            }else{
                ll l=x,r=n;
                while(r-l>1){
                    ll mid=(r+l)/2;
                    d=seg.query(x,mid);
                    if(v<=d)r=mid;
