    int T, X, Y;
    scanf("%d %d %d", &T, &X, &Y);
    if(T==1) seg.update(X-1,Y);
    else if(T==2) printf("%d\n", seg.query(X-1,Y));
    else{
      int a=seg.find_first(X-1,[&](int b){return b>=Y;});
      if(a==-1) a=N;
      printf("%d\n", a+1);
    }
  }
  return 0;
}

