struct SegmentTree
{
    using T = int;

    int N;
    vector<T> dat;

    T id = -INF;
    T F(T &a, T &b) { return max(a, b); }

    SegmentTree(int n){
        N = 1;
        while(n > N) N = N << 1;
        dat = vector<T>(2 * N - 1, id);
    }

    SegmentTree(int n, vector<T> &v){
        N = 1;
        while(n > N) N = N << 1;
        dat = vector<T>(2 * N - 1, id);
        for(int i = 0; i < n; i++) dat[i + N - 1] = v[i];
        for(int i = N - 2; i >= 0; i--) dat[i] = F(dat[i * 2 + 1], dat[i * 2 + 2]); 
    }

    SegmentTree(){}


    void update(int k, T a){
        k += N - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            dat[k] = F(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    void reset() { fill(dat.begin(), dat.end(), id); }

    T get(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return id;
        if(a <= l && r <= b) return dat[k];
        else{
            T vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
            return F(vl, vr);
        }
    }
    T get(int a, int b) { return get(a, b, 0, 0, N); }

    T val(int k){ return dat[k + N - 1]; }

};

signed main(){

    int N, Q; cin >> N >> Q;
    vec A(N); cin >> A;
    SegmentTree ST(N, A);

    REP(_, Q){
        int t; cin >> t;
        if(t == 1){
            int x, v; cin >> x >> v;
            x--;
            ST.update(x, v);
        }else if(t == 2){
            int l, r; cin >> l >> r;
            l--; r--;
            int ans = ST.get(l, r + 1);
            Out(ans);
        }else{
            int x, v; cin >> x >> v;
            x--;
            int i0 = x - 1, i1 = N;
            while(i1 - i0 > 1){
                int i = (i0 + i1) / 2;
                if(ST.get(x, i + 1) >= v) i1 = i;
                else i0 = i;
            }
            Out(i1 + 1);
        }
    }

    return 0;
}

