const int N=2e5+1;
ll ma[N*4];
int n,q;

void update(int l,int r,int id,int i,int v){
    if(l==r){
        ma[id]=v;
        return;
    }
    int mid=(l+r)>>1;
    if(i<=mid)update(l,mid,id*2,i,v);
    else update(mid+1,r,id*2+1,i,v);
    ma[id]=max(ma[id*2],ma[id*2+1]);
}
ll query_mi(int l,int r,int ql,int qr,int v,int id){
    if(l>qr||r<ql)return -1;
    if(l==r){
        if(ma[id]>=v)return l;
        else return -1;
    }
    int mid=(l+r)>>1;
    int ans=-1;
    if(ql<mid)ans=query_mi(l,mid,ql,qr,v,id*2);
    if(ans!=-1)return ans;
    if(qr>mid)ans=query_mi(mid+1,r,ql,qr,v,id*2+1);
    return ans;
}
ll query_ma(int l,int r,int ql,int qr,int id){
    if(l>qr||r<ql)return -1;
    if(l>=ql&&r<=qr)return ma[id];
    int mid=(l+r)>>1;
    if(ql<mid)query_ma(l,mid,ql,qr,id*2);
    if(qr>mid)query_ma(mid+1,r,ql,qr,id*2+1);
    ma[id]=max(ma[id*2],ma[id*2+1]);
    return ma[id];
}

