			int L, R; cin >> L >> R;
			cout << s.prod(--L, R) << endl;

		} else if (T == 3) {
			int X, V; cin >> X >> V;
			function<bool(int)> f = [&](int x) {
				return x < V;
			};
			cout << s.max_right<function<bool(int)>>(--X, f) + 1 << endl;
		}

		// show(s);
	}
}

