        }else if(t==3){
            --a;
            int l = a,r = n+1;
            while(r - l > 1){
                int m = (l+r)/2;
                if(seg.query(a,m)<b) l = m;
                else r = m;
            }
            cout << l+1 << endl;
        }
        /*
        rep(i,n){
