template <typename T>
struct SegmentTree{
  using F = function<T(T,T)>;
  int n,n_;
  F f;
  T ti;
  vector<T> dat;
  SegmentTree(){};
  SegmentTree(F f,T ti):f(f),ti(ti){}

  void init(){
    n=1;
    while(n<n_) n<<=1;
    dat.assign(n<<1,ti);
  }

  void build(const vector<T> &v){
    n_=v.size();
    init();
    for(int i=0;i<n_;i++) dat[n+i]=v[i];
    for(int i=n-1;i;i--)
      dat[i]=f(dat[(i<<1)|0],dat[(i<<1)|1]);
  }

  void update(int k,T x){
    assert(0 <= k && k < n_);
    dat[k+=n]=x;
    while(k>>=1)
      dat[k]=f(dat[(k<<1)|0],dat[(k<<1)|1]);
  }

  void add(int k,T x){
    assert(0 <= k && k < n_);
    dat[k+=n]+=x;
    while(k>>=1)
      dat[k]=f(dat[(k<<1)|0],dat[(k<<1)|1]);
  }

  T get(int k){
    assert(0 <= k && k < n_);
    return dat[n+k];
  }

  T query(int a,int b){
    assert(0 <= a && a <= b && b <= n_);
    T vl=ti, vr=ti;
    for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
      if(l&1) vl=f(vl,dat[l++]);
      if(r&1) vr=f(dat[--r],vr);
    }
    return f(vl,vr);
  }

  template <class C> int max_right(int l, C check) {
    assert(0 <= l && l <= n_);
    if (l == n_) return n_;
    l += n;
    T sm = ti;
    do {
      while (l % 2 == 0) l >>= 1;
      if (!check(f(sm, dat[l]))) {
        while (l < n) {
          l = (2 * l);
          if (check(f(sm, dat[l]))) {
            sm = f(sm, dat[l]);
            l++;
          }
        }
        return l - n;
      }
      sm = f(sm, dat[l]);
      l++;
    } while ((l & -l) != l);
    return n_;
  }

  template <class C> int min_left(int r, C check) {
    assert(0 <= r && r <= n_);
    if (r == 0) return 0;
    r += n;
    T sm = ti;
    do {
      r--;
      while (r > 1 && (r % 2)) r >>= 1;
      if (!check(f(dat[r], sm))) {
        while (r < n) {
          r = (2 * r + 1);
          if (check(f(dat[r], sm))) {
            sm = f(dat[r], sm);
            r--;
          }
        }
        return r + 1 - n;
      }
      sm = f(dat[r], sm);
    } while ((r & -r) != r);
    return 0;
  }
};

