signed main() {
	INIT;

	VAR(int, n, Q);
	VEC(int, a, n);

	a.emplace_back(INFINT);
	SegmentTree<Monoid::max<int>> st(a);
	REP(_, Q) {
		VAR(int, t, l, r);
		if (t == 1) {
			st.update(--l, r);
		}
		else if (t == 2) {
			OUT(st.query(--l, r))BR;
		}
		else {
			--l;
			if (st.query(l, l + 1) >= r) { OUT(l + 1)BR; }
			else {
				int ok = n + 1, ng = l;
				while ((ok - ng) > 1) {
					int me = (ok + ng) / 2;
					if (st.query(l, me) >= r) ok = me;
					else ng = me;
				}
				OUT(ok)BR;
			}
		}
	}

	return 0;
}

