	int N, Q;
	cin >> N >> Q;

	auto f = [&](int a, int b) {return max(a, b); };
	SegmentTree<int> st(N, f, 0);

	vector<int> P(N);
	rep(i, 0, N)cin >> P[i];
	st.init(P);

