        seg.set(i, x);
    }
    seg.build();
    while(q--){
        int t, a, b;
        scanf("%d %d %d", &t, &a, &b);
        if(t == 1){
            seg.update(a-1, b);
        }else if(t == 2){
            printf("%d\n", seg.query(a-1, b));
        }else if(t == 3){
            printf("%d\n", seg.search_right(a-1, [&](int x){ return x < b; })+1);
        }
    }
    return 0;
}

