template <class Monoid>
class SegmentTree{
  public:
    int n;
    using T = typename Monoid::value_type;
    vector<T> val;
    T identity;

    SegmentTree(){}
    SegmentTree(int n_, vector<T> v=vector<T>()){
      n = 1;
      while(n < n_)n *= 2;
      identity = Monoid::identity;
      val.assign(2*n-1, identity);

      for(size_t i = 0; i < v.size(); i++){
        val[i+n-1] = v[i];
      }
      for(int i = n - 2; i >= 0; i--){
        val[i] = Monoid::operation(val[2*i+1], val[2*i+2]);
      }
    }
    void update(int k, const T &t){
      k = k + n - 1;
      val[k] = t;
      while(k > 0){
        k = (k - 1) / 2;
        val[k] = Monoid::operation(val[2*k+1], val[2*k+2]);
      }
    }
    T query(int a, int b, int k, int l, int r){
      if(r <= a || b <= l)return identity;
      if(a <= l && r <= b)return val[k];
      T lv = query(a, b, 2*k+1, l, (l+r)/2);
      T rv = query(a, b, 2*k+2, (l+r)/2, r);
      return Monoid::operation(lv, rv);
    }
    T query(int a, int b){
      return query(a, b, 0, 0, n);
    }
    T get(int i){
      return val[i+n-1];
    }
};

template <typename T>
class RMQ{
  public:
    const static T identity;
    using value_type = T;

    RMQ(){}
    static T operation(T &l, T &r){
      return max(l, r);
    }
};

template <typename T>
const T RMQ<T>::identity = numeric_limits<T>::min();


int main(int argc, char const* argv[])
{
  int n, q; cin >> n >> q;
  vector<ll> a(n); cin >> a;
  SegmentTree<RMQ<ll>> seg(n, a);
  rep(i, q){
    int t; cin >> t;
    if(t == 1){
      int x; cin >> x; x--;
      ll v; cin >> v;
      seg.update(x, v);
    }else if(t == 2){
      int l, r; cin >> l >> r; l--;
      cout << seg.query(l, r) << "\n";
    }else{
      int x; cin >> x; x--;
      ll v; cin >> v;
      if(seg.query(x, n) < v)cout << n + 1 << endl;
      else{
        int ld = x - 1, rd = n - 1;
        while(rd - ld > 1){
          int md = (rd + ld) / 2;
          ll s = seg.query(x, md + 1);
          if(s < v)ld = md;
          else rd = md;
        }
        cout << rd + 1 << "\n";
      }
    }
  }
  cout << flush;
  return 0;
}

