int main() {
  ll N, Q; cin >> N >> Q;
  ll A[N]; rep(i,N) cin >> A[i];

  SegTree st(N); rep(i,N) st.update(i,A[i]);
  rep(_,Q) {
    ll t, x, y; cin >> t >> x >> y; x--;
    if (t==1) st.update(x,y);
    else if (t==2) cout << st.query(x,y) << endl;
    else if (t==3) {
      ll l = x, r = N+1;
      while (l!=r) {
        ll mid = (l+r)/2;
        if (st.query(x,mid)>=y) r = mid;
        else l = mid+1;
      }
      cout << l << endl;
    }
  }
  // cout << result << endl;
  return 0;
}

