inline int read_int() {
    int ret = 0;
    while ((*o == ' ' || *o == '\n') && *o != '\0') o++;

    while (*o >= '0' && *o <= '9') {
        ret *= 10;
        ret += *o - '0';
        *o++;
    }
    return ret;
}

struct Monoid {
    using value_type = int;
    inline static int identity() {
        return -1;
    };
    inline static int operation(int a, int b) {
        return max(a, b);
    };
};

