    q = read_int();

    vector<int> v(n);
    for (auto &vs:v) vs = read_int();
    SegmentTree<Monoid> seg(v.begin(), v.end());

    int com, a, b;
    int tmp;

    auto f = [&](int x){
        if (x >= b) return true;
        else return false;
    };
    while (q--) {
        com = read_int();
