            out.emplace_back(seg.get(l,r+1));
        }
        else{

            int x;ll v;cin >> x >> v;x--;//continue;
            out.emplace_back(seg.lower_bound(x,v)+1);
        }
    }
    rep(i,out.size())cout << out[i] << '\n';
}

