/**
 * @title Max monoid
 * @docs max.md
 */
namespace haar_lib {
  template <typename T>
  struct max_monoid {
    using value_type = std::optional<T>;

    value_type operator()() const {return {};}
    value_type operator()(const value_type &a, const value_type &b) const {
      if(not a) return b;
      if(not b) return a;
      return {std::max(*a, *b)};
    }
  };
}

/**
 * @title Segment tree
 * @docs segment_tree.md
 */
namespace haar_lib {
  template <typename Monoid>
  class segment_tree {
    using value_type = typename Monoid::value_type;
    const static Monoid M;

    int depth, size, hsize;
    std::vector<value_type> data;

  public:
    segment_tree(){}
    segment_tree(int n):
      depth(n > 1 ? 32 - __builtin_clz(n - 1) + 1 : 1),
      size(1 << depth), hsize(size / 2),
      data(size, M())
    {}

    auto operator[](int i) const {return data[hsize + i];}

    auto get(int x, int y) const {
      value_type ret_left = M();
      value_type ret_right = M();

      int l = x + hsize, r = y + hsize;
      while(l < r){
        if(r & 1) ret_right = M(data[--r], ret_right);
        if(l & 1) ret_left = M(ret_left, data[l++]);
        l >>= 1, r >>= 1;
      }

      return M(ret_left, ret_right);
    }

    void update(int i, const value_type &x){
      i += hsize;
      data[i] = x;
      while(i > 1) i >>= 1, data[i] = M(data[i << 1 | 0], data[i << 1 | 1]);
    }

    template <typename T>
    void init_with_vector(const std::vector<T> &val){
      data.assign(size, M());
      for(int i = 0; i < (int)val.size(); ++i) data[hsize + i] = val[i];
      for(int i = hsize - 1; i >= 1; --i) data[i] = M(data[i << 1 | 0], data[i << 1 | 1]);
    }

    template <typename T>
    void init(const T &val){
      init_with_vector(std::vector<value_type>(hsize, val));
    }

    template <typename F = std::less<value_type>>
    int lower_bound(int l, int r, value_type x, F f = F()) const {
      std::deque<int> p;
      int L = l + hsize;
      int R = r + hsize;
      while(L < R){
        if(R & 1) p.push_back(--R);
        if(L & 1) p.push_front(L++);
        L >>= 1, R >>= 1;
      }

      value_type a = M();

      for(int i : p){
        if(not f(M(a, data[i]), x)){

          while(i < hsize){
            if(not f(M(a, data[i << 1 | 0]), x)){
              i = i << 1 | 0;
            }else{
              i = i << 1 | 1;
              a = M(a, data[i << 1 | 0]);
            }
          }

          return i - hsize;
        }
        a = M(a, data[i]);
      }

      return r;
    }
  };
}


namespace solver {
  using namespace haar_lib;

  void init(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    std::cout << std::fixed << std::setprecision(12);
    std::cerr << std::fixed << std::setprecision(12);
    std::cin.exceptions(std::ios_base::failbit);
  }

  void solve(){
    int N, Q; std::cin >> N >> Q;
    std::vector<int> a(N); std::cin >> a;
    auto seg = segment_tree<max_monoid<int>>(N);
    seg.init_with_vector(a);

    for(int i = 0; i < Q; ++i){
      int type; std::cin >> type;

      if(type == 1){
        int x, v; std::cin >> x >> v;
        seg.update(x - 1, v);
      }else if(type == 2){
        int l, r; std::cin >> l >> r;
        std::cout << *seg.get(l - 1, r) << "\n";
      }else{
        int x, v; std::cin >> x >> v;

        std::cout << seg.lower_bound(
          x - 1, N, v,
          [v](const auto &a, const auto &b){return a.value_or(INT_MAX) < b.value_or(INT_MAX);}
        ) + 1 << "\n";
      }
    }
  }
}

