int main() {
	using namespace cplib;

	int n, q; scanf("%d%d", &n, &q);
	std::vector<int> a(n); for(auto& v: a) scanf("%d", &v);

	using T = max_monoid<int, -1>;
	segment_tree<T> seg(n);
	for(int i = 0; i < n; i++) seg.set(i, T{a[i]});
	seg.build();

	while(q--) {
		int type, x, y; scanf("%d%d%d", &type, &x, &y);

		if(type == 1) seg.change(x - 1, T{y});
		if(type == 2) printf("%d\n", seg.fold(x - 1, y).a);
		if(type == 3) {
			auto f = [&](const T& r) -> bool { return r.a < y; };
			printf("%d\n", seg.search_right(x - 1, f) + 1);
		}
	}
	return 0;
}

