void update(int p, int x) {
    tr[p | M] = x;
    for (p = (p | M) >> 1; p != 0; p >>= 1)
        tr[p] = max(tr[p << 1], tr[p << 1 | 1]);
}

int query(int l, int r) {
    int res = -1;
    for (l += M - 1, r += M + 1; (l ^ r) != 1; l >>= 1, r >>= 1) {
        if ((~l & 1) == 1)
            res = max(res, tr[l ^ 1]);
        if ((r & 1) == 1)
            res = max(res, tr[r ^ 1]);
    }
    return res;
}

