solve :: Int -> Int -> U.Vector Int -> U.Vector (Int, Int, Int) -> U.Vector Int
solve n q xs qs = runST $ do
    seg <- buildSegTree $ U.map Max xs
    fmap (U.map snd.U.filter((/= (1 :: Int)).fst))$ U.forM qs $ \case
        (1, x, v) -> do
            writeSegTree seg (x - 1) (Max v)
            return (1, -1)
        (2, l, r) -> do
            res <- getMax <$>  mappendFromTo seg (l - 1) r
            return (2, res)
        (3, x, v) -> do
            res <- min n <$> maxRightSegTree seg (x - 1) (< Max v)
            return (3, res + 1)

