                int v = in.nextInt();
                int ans = tree.binarySearchRight(0, x + 1, e -> e < v);
                if (!(ans == -1 || (tree.get(ans - 1, n) >= v && tree.get(ans, n) < v))) {
                    throw new RuntimeException();
                }
                out.println(ans == -1 ? n + 1 : n - ans + 1);
            }
        }
    }

