public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	LazySegTree st = new LazySegTree(a,
			-INF, (ele1, ele2) -> max(ele1, ele2),
			-INF, (ele1, ele2) -> ele2,
			(ele1, ele2) -> ele2);
	for(int q = 0; q < query; q ++) {
		int idx;
		switch(ni()) {
		case 1: idx = ni() - 1; st.update(idx, idx + 1, nl()); break;
		case 2: prtln(st.find(ni() - 1, ni())); break;
		case 3:
			idx = ni() - 1;
			long v = nl();
			int ans = st.findLeftmost(idx, (ele) -> ele >= v);
			prtln(ans < 0 ? num + 1 : ans + 1);
			break;
		}
	}
}

class SegTree {
	long e;
	LongBinaryOperator f;

	int n;
	long nodes[];
	int rangeL[];
	int rangeR[];

	SegTree(long[] a, long e, LongBinaryOperator f) { init(a, e, f); } // O(N)
	SegTree(int len, long x, long e, LongBinaryOperator f) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f);
	}
	SegTree(int len, long e, LongBinaryOperator f) { init(len, e, f); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f) { // O(N)
		init(a.length, e, f);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, long e, LongBinaryOperator f) { // O(N)
		this.e = e;
		this.f = f;
		n = 1;
		while(n < len) n <<= 1;
		nodes = new long[n << 1];
		fill(nodes, e);
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++)  { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void set(int i, long val) { // O(logN)
		i += n;
		nodes[i] = val;
		while(i > 1) {
			i >>= 1;
			nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
		}
	}
	void update(int i, long val) { set(i, f.applyAsLong(nodes[i + n], val)); } // O(logN)

	long get(int i) { return nodes[i + n]; } // O(1)

	long find(int l, int r) { // O(logN)
		l += n; r += n;
		long xL = e;
		long xR = e;
		while(l < r) {
			if((l & 1) != 0) xL = f.applyAsLong(xL, nodes[l ++]);
			if((r & 1) != 0) xR = f.applyAsLong(nodes[-- r], xR);
			l >>= 1; r >>= 1;
		}
		return f.applyAsLong(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int l, LongPredicate check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, LongPredicate check){
		long crt = e;
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			long tmp = f.applyAsLong(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int r, LongPredicate check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			long tmp = f.applyAsLong(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

@FunctionalInterface
interface LongLazyOperator { long applyAsLong(long t, long u); }
// interface LongLazyOperator { long applyAsLong(long t, long u, int v); }
class LazySegTree {
	long e;
	LongBinaryOperator f;
	long e2;
	LongBinaryOperator g;
	LongLazyOperator h;

	int n;
	int height;
	long nodes[];
	long lazy[];
	int rangeL[];
	int rangeR[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { init(a, e, f, e2, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { init(len, e, f, e2, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { // O(N)
		init(a.length, e, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, long e, LongBinaryOperator f, long e2, LongBinaryOperator g, LongLazyOperator h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		height = 0;
		while(n < len) { n <<= 1; height ++; }
		nodes = new long[n << 1];
		fill(nodes, e);
		lazy = new long[n << 1];
		fill(lazy, e2);
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++)  { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void eval(int k) { // O(1)
		if(lazy[k] != e2) {
			nodes[k] = h.applyAsLong(nodes[k], lazy[k]);
			// nodes[k] = h.applyAsLong(nodes[k], lazy[k], r - l);
			if(k < n) {
				lazy[k << 1] = g.applyAsLong(lazy[k << 1], lazy[k]);
				lazy[(k << 1) + 1] = g.applyAsLong(lazy[(k << 1) + 1], lazy[k]);
			}
			lazy[k] = e2;
		}
	}

	void update(int l, int r, long val) { // O(logN)
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		int l0 = l;
		int r0 = r;
		r ++;
		while(l < r) {
			if((l & 1) != 0) { lazy[l] = g.applyAsLong(lazy[l], val); eval(l); l ++; }
			if((r & 1) != 0) { r --; lazy[r] = g.applyAsLong(lazy[r], val); eval(r); }
			l >>= 1; r >>= 1;
		}
		while(l0 > 1) {
			l0 >>= 1;
			nodes[l0] = f.applyAsLong(nodes[l0 << 1], nodes[(l0 << 1) + 1]);
		}
		while(r0 > 1) {
			r0 >>= 1;
			nodes[r0] = f.applyAsLong(nodes[r0 << 1], nodes[(r0 << 1) + 1]);
		}
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int l, int r) {
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		r ++;
		long xL = e;
		long xR = e;
		while(l < r) {
			if((l & 1) != 0) { eval(l); xL = f.applyAsLong(xL, nodes[l]); l ++; }
			if((r & 1) != 0) { r --; eval(r); xR = f.applyAsLong(nodes[r], xR); }
			l >>= 1; r >>= 1;
		}
		return f.applyAsLong(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int l, LongPredicate check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			eval(idx);
			long tmp = f.applyAsLong(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int r, LongPredicate check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			eval(idx);
			long tmp = f.applyAsLong(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

	}
}

import java.util.*;
import java.util.function.*;

class Internal {
	static int ceil_pow2(int n) {
		int x = 0;
		while ((1 << x) < n)
			x++;
		return x;
	}
}

class SegTree<S> {
	private final BinaryOperator<S> op;
	private final Supplier<S> e;

	private final int _n;
	private final int size;
	private final int log;
	private final S[] d;

	@SuppressWarnings("unchecked")
	private static <S> S[] makeArrayList(int n, Supplier<S> s) {
		S[] l = (S[]) new Object[n];
		for (int i = 0; i < n; ++i)
			l[i] = (s.get());
		return l;
	}

	public SegTree(BinaryOperator<S> op, Supplier<S> e, S[] v) {
		this.op = op;
		this.e = e;

		_n = v.length;

		log = Internal.ceil_pow2(_n);
		size = 1 << log;
		d = makeArrayList(2 * size, e);

		System.arraycopy(v, 0, d, size, _n);

		for (int i = size - 1; i >= 1; i--)
			update(i);
	}

	public SegTree(BinaryOperator<S> op, Supplier<S> e, List<S> v) {
		this.op = op;
		this.e = e;

		_n = v.size();

		log = Internal.ceil_pow2(_n);
		size = 1 << log;
		d = makeArrayList(2 * size, e);

		//定数時間accessでないListを考えてループ対象を変更
		int j = 0;
		for (S s : v) {
			d[size + j] = s;
			j++;
		}

		for (int i = size - 1; i >= 1; i--)
			update(i);
	}

	public SegTree(BinaryOperator<S> op, Supplier<S> e, int n) {
		this.op = op;
		this.e = e;

		_n = n;

		log = Internal.ceil_pow2(_n);
		size = 1 << log;
		d = makeArrayList(2 * size, e);
		for (int i = size - 1; i >= 1; i--)
			update(i);
	}

	/*
	public SegTree(BinaryOperator<S> op, Supplier<S> e) {
		this(op, e, 0);
	}
	*/

	public void set(int p, S x) {
		assert (0 <= p && p < _n);
		p += size;
		d[p] = x;
		for (int i = 1; i <= log; i++)
			update(p >> i);
	}

	public S get(int p) {
		assert (0 <= p && p < _n);
		return d[p + size];
	}

	public S prod(int l, int r) {
		assert (0 <= l && l <= r && r <= _n);
		S sml = e.get(), smr = e.get();
		l += size;
		r += size;

		while (l < r) {
			if ((l & 1) > 0)
				sml = op.apply(sml, d[l++]);
			if ((r & 1) > 0)
				smr = op.apply(d[--r], smr);
			l >>= 1;
			r >>= 1;
		}
		return op.apply(sml, smr);
	}

	public S all_prod() {
		return d[1];
	}

	public int max_right(int l, Predicate<S> f) {
		assert (0 <= l && l <= _n);
		assert (f.test(e.get()));
		if (l == _n)
			return _n;
		l += size;
		S sm = e.get();
		do {
			while (l % 2 == 0)
				l >>= 1;
			if (!f.test(op.apply(sm, d[l]))) {
				while (l < size) {
					l = 2 * l;
					if (f.test(op.apply(sm, d[l]))) {
						sm = op.apply(sm, d[l]);
						l++;
					}
				}
				return l - size;
			}
			sm = op.apply(sm, d[l]);
			l++;
		} while ((l & (-l)) != l);
		return _n;
	}

	public int min_left(int r, Predicate<S> f) {
		assert (0 <= r && r <= _n);
		assert (f.test(e.get()));
		if (r == 0)
			return 0;
		r += size;
		S sm = e.get();
		do {
			r--;
			while (r > 1 && (r % 2 > 0))
				r >>= 1;
			if (!f.test(op.apply(d[r], sm))) {
				while (r < size) {
					r = 2 * r + 1;
					if (f.test(op.apply(d[r], sm))) {
						sm = op.apply(d[r], sm);
						r--;
					}
				}
				return r + 1 - size;
			}
			sm = op.apply(d[r], sm);
		} while ((r & -r) != r);
		return 0;
	}

	private void update(int k) {
		d[k] = op.apply(d[2 * k], d[2 * k + 1]);
	}
}

