public void solve() {
	int num = ni();
	int query = ni();
	// long a[] = nl(num);
	Long a[] = new Long[num];
	for(int i = 0; i < num; i ++) a[i] = nl();
	reverse(a);
	SegTree<Long> st = new SegTree<>(a,
			() -> -INF, (ele1, ele2) -> max(ele1, ele2));
	for(int q = 0; q < query; q ++) {
		int idx;
		switch(ni()) {
		case 1: st.set(num - ni(), nl()); break;
		case 2: idx = num - ni() + 1; prtln(st.find(num - ni(), idx)); break;
		case 3:
			idx = num - ni() + 1;
			long v = nl();
			int ans = st.findRightmost(idx, (ele) -> ele >= v);
			prtln(ans < 0 ? num + 1 : num + 1 - ans);
			break;
		}
	}
}

class SegTree<T> {
	Supplier<T> eSupplier;
	T e;
	BinaryOperator<T> f;

	int n;
	T nodes[];
	int rangeL[];
	int rangeR[];

	SegTree(T[] a, Supplier<T> eSupplier, BinaryOperator<T> f) { init(a, eSupplier, f); } // O(N)
	SegTree(int len, Supplier<T> xSupplier, Supplier<T> eSupplier, BinaryOperator<T> f) { // O(N)
		@SuppressWarnings("unchecked")
		T a[] = (T[]) new Object[len];
		for(int i = 0; i < len; i ++) a[i] = xSupplier.get();
		init(a, eSupplier, f);
	}
	SegTree(int len, Supplier<T> eSupplier, BinaryOperator<T> f) { init(len, eSupplier, f); } // O(N)

	void init(T[] a, Supplier<T> eSupplier, BinaryOperator<T> f) { // O(N)
		init(a.length, eSupplier, f);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.apply(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, Supplier<T> eSupplier, BinaryOperator<T> f) { // O(N)
		this.eSupplier = eSupplier;
		this.e = eSupplier.get();
		this.f = f;
		n = 1;
		while(n < len) n <<= 1;
		@SuppressWarnings("unchecked")
		T tmp[] = (T[]) new Object[n << 1];
		this.nodes = tmp;
		for(int i = 0; i < nodes.length; i ++) nodes[i] = eSupplier.get();
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++)  { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.apply(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void set(int i, T val) { // O(logN)
		i += n;
		nodes[i] = val;
		while(i > 1) {
			i >>= 1;
			nodes[i] = f.apply(nodes[i << 1], nodes[(i << 1) + 1]);
		}
	}
	void update(int i, T val) { set(i, f.apply(nodes[i + n], val)); } // O(logN)

	T get(int i) { return nodes[i + n]; } // O(1)

	T find(int l, int r) { // O(logN)
		l += n; r += n;
		T xL = eSupplier.get();
		T xR = eSupplier.get();
		while(l < r) {
			if((l & 1) != 0) xL = f.apply(xL, nodes[l ++]);
			if((r & 1) != 0) xR = f.apply(nodes[-- r], xR);
			l >>= 1; r >>= 1;
		}
		return f.apply(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(Predicate<T> check) { return findLeftmost(0, check); }
	int findLeftmost(int l, Predicate<T> check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, Predicate<T> check) {
		T crt = eSupplier.get();
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			T tmp = f.apply(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(Predicate<T> check) { return findRightmost(n, check); }
	int findRightmost(int r, Predicate<T> check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, Predicate<T> check) {
		T crt = eSupplier.get();
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			T tmp = f.apply(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

	}
}

import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Scanner;
import java.util.function.BinaryOperator;
