public class Main {
    public static void main(String[] args) {
        var sc = new Scanner(System.in);
        var pw = new PrintWriter(System.out);
        final int N = Integer.parseInt(sc.next());
        final int Q = Integer.parseInt(sc.next());
        final var A = new Integer[N];
        Arrays.setAll(A, i -> Integer.parseInt(sc.next()));
        var t = new SegTree<Integer>(A, 0, Integer::max);
        for (int $ = 0; $ < Q; $++) {
            int query = Integer.parseInt(sc.next());
            int a = Integer.parseInt(sc.next()) - 1;
            int b = Integer.parseInt(sc.next());
            switch (query) {
                case 1:
                    t.set(a, b);
                    break;
                case 2:
                    pw.println(t.prod(a, b));
                    break;
                case 3:
                    pw.println(t.maxRight(a, x -> x < b) + 1);
                default:
                    break;
            }
        }
        sc.close();
        pw.flush();
        pw.close();
    }
}

class SegTree<S> {
    final int MAX;

    final int N;
    final S E;
    final BinaryOperator<S> Op;

    final S[] Dat;

    @SuppressWarnings("unchecked")
    public SegTree(int n, S e, BinaryOperator<S> op) {
        this.MAX = n;
        int k = 1;
        while (k < n) k <<= 1;
        this.N = k;
        this.E = e;
        this.Op = op;
        this.Dat = (S[]) new Object[N << 1];
        Arrays.fill(Dat, E);
    }

    public SegTree(S[] dat, S e, BinaryOperator<S> op) {
        this(dat.length, e, op);
        build(dat);
    }

    private void build(S[] dat) {
        int l = dat.length;
        System.arraycopy(dat, 0, Dat, N, l);
        for (int i = N - 1; i > 0; i--) {
            Dat[i] = Op.apply(Dat[i << 1 | 0], Dat[i << 1 | 1]);
        }
    }

    public void set(int p, S x) {
        exclusiveRangeCheck(p);
        Dat[p += N] = x;
        p >>= 1;
        while (p > 0) {
            Dat[p] = Op.apply(Dat[p << 1 | 0], Dat[p << 1 | 1]);
            p >>= 1;
        }
    }

    public S get(int p) {
        exclusiveRangeCheck(p);
        return Dat[p + N];
    }

    public S prod(int l, int r) {
        if (l > r) {
            throw new IllegalArgumentException("TODO");
        }
        inclusiveRangeCheck(l);
        inclusiveRangeCheck(r);
        S sumLeft = E;
        S sumRight = E;
        l += N; r += N;
        while (l < r) {
            if ((l & 1) == 1) sumLeft = Op.apply(sumLeft, Dat[l--]);
            if ((r & 1) == 1) sumRight = Op.apply(Dat[--r], sumRight);
            l >>= 1; r >>= 1;
        }
        return Op.apply(sumLeft, sumRight);
    }

    public S allProd() {
        return Dat[1];
    }

    public int maxRight(int l, Predicate<S> f) {
        inclusiveRangeCheck(l);
        if (!f.test(E)) {
            throw new IllegalArgumentException("TODO");
        }
        if (l == MAX) return MAX;
        l += N;
        S sum = E;
        do {
            l >>= Integer.numberOfTrailingZeros(l);
            if (!f.test(Op.apply(sum, Dat[l]))) {
                while (l < N) {
                    l = l << 1;
                    if (f.test(Op.apply(sum, Dat[l]))) {
                        sum = Op.apply(sum, Dat[l]);
                        l++;
                    }
                }
                return l - N;
            }
            sum = Op.apply(sum, Dat[l]);
            l++;
        } while ((l & -l) != l);
        return MAX;
    }

    public int minLeft(int r, Predicate<S> f) {
        inclusiveRangeCheck(r);
        if (!f.test(E)) {
            throw new IllegalArgumentException("TODO");
        }
        if (r == 0) return 0;
        r += N;
        S sum = E;
        do {
            r--;
            while (r > 1 && (r & 1) == 1) r >>= 1;
            if (!f.test(Op.apply(Dat[r], sum))) {
                while (r < N) {
                    r = r << 1 | 1;
                    if (f.test(Op.apply(Dat[r], sum))) {
                        sum = Op.apply(Dat[r], sum);
                        r--;
                    }
                }
                return r + 1 - N;
            }
            sum = Op.apply(Dat[r], sum);
        } while ((r & -r) != r);
        return 0;
    }

    private void exclusiveRangeCheck(int p) {
        if (p < 0 || p >= MAX) {
            throw new IndexOutOfBoundsException(
                "TODO"
            );
        }
    }

    private void inclusiveRangeCheck(int p) {
        if (p < 0 || p > MAX) {
            throw new IndexOutOfBoundsException(
                "TODO"
            );
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;
import java.util.function.*;

public class Main {
    static In in = new In();
    static Out out = new Out();
    static final long inf = 0x1fffffffffffffffL;
    static final int iinf = 0x3fffffff;
    static final double eps = 1e-9;
    static long mod = 1000000007;

    void solve(boolean naive) {
        int n = in.nextInt();
        int q = in.nextInt();
        List<Long> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            list.add(in.nextLong());
        }
        Collections.reverse(list);
        SegmentTree<Long> tree = new SegmentTree<>(Monoid.MAX_LONG);
        tree.build(list);
        for (int i = 0; i < q; i++) {
            int t = in.nextInt();
            if (t == 1) {
                int x = n - in.nextInt();
                long v = in.nextLong();
                tree.set(x, v);
            } else if (t == 2) {
                int l = n - in.nextInt();
                int r = n - in.nextInt();
                out.println(tree.get(r, l));
            } else {
                int x = n - in.nextInt();
                int v = in.nextInt();
                int ans = tree.binarySearchRight(0, x + 1, e -> e >= v);
                out.println(ans == -1 ? n + 1 : n - ans + 1);
            }
        }
    }

    public static void main(String[] args) {
        new Main().solve(args.length == 1 && args[0].equals("naive"));
        out.flush();
    }
}

class Monoid<T> {
    static final Monoid<Integer> SUM_INTEGER = new Monoid<>(0, Integer::sum);
    static final Monoid<Integer> PRODUCT_INTEGER = new Monoid<>(1, (a, b) -> a * b);
    static final Monoid<Integer> XOR_INTEGER = new Monoid<>(0, (a, b) -> a ^ b);
    static final Monoid<Integer> GCD = new Monoid<>(0, (a, b) -> {
        if (b == 0) {
            return a;
        }
        while (a % b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return b;
    });
    static final Monoid<Integer> MIN_INTEGER = new Monoid<>(Main.iinf, Math::min);
    static final Monoid<Integer> MAX_INTEGER = new Monoid<>(-Main.iinf, Math::max);
    static final Monoid<Long> SUM_LONG = new Monoid<>(0L, Long::sum);
    static final Monoid<Long> PRODUCT_LONG = new Monoid<>(1L, (a, b) -> a * b);
    static final Monoid<Long> XOR_LONG = new Monoid<>(0L, (a, b) -> a ^ b);
    static final Monoid<Long> MIN_LONG = new Monoid<>(Main.inf, Math::min);
    static final Monoid<Long> MAX_LONG = new Monoid<>(-Main.inf, Math::max);
    static final Monoid<Long> SUM_MOD = new Monoid<>(0L, (a, b) -> (a + b) % Main.mod);
    private T identity;
    private Supplier<T> identitySupplier;
    private BinaryOperator<T> operation;

    Monoid(BinaryOperator<T> operation) {
        this.operation = operation;
    }

    Monoid(T identity, BinaryOperator<T> operation) {
        this(operation);
        this.identity = identity;
    }

    Monoid(Supplier<T> identitySupplier, BinaryOperator<T> operation) {
        this(operation);
        this.identitySupplier = identitySupplier;
    }

    T merge(T x, T y) {
        T identity = identity();
        if (Objects.equals(x, identity)) {
            if (Objects.equals(y, identity)) {
                return identity;
            }
            return y;
        } else if (Objects.equals(y, identity)) {
            return x;
        } else {
            return operation.apply(x, y);
        }
    }

    public T identity() {
        return identitySupplier == null ? identity : identitySupplier.get();
    }

    public boolean equalsIdentity(T obj) {
        return Objects.equals(obj, identity());
    }
}

class SegmentTree<T> {
    private boolean isBuilt;
    private List<T> node;
    private int n;
    private int m;
    private Monoid<T> monoid;
    private int[] left;
    private int[] right;

    SegmentTree(Monoid<T> monoid) {
        this.monoid = monoid;
    }

    void build(int m) {
        build(m, i -> monoid.identity());
    }

    void build(int m, T init) {
        build(m, i -> init);
    }

    void build(List<T> data) {
        build(data.size(), data::get);
    }

    void build(int m, IntFunction<T> initFunc) {
        this.m = m;
        this.n = Integer.highestOneBit(m * 2 - 1);
        this.node = new ArrayList<>(n * 2);
        this.left = new int[n * 2];
        this.right = new int[n * 2];
        for (int i = 0; i < n; i++) {
            node.add(null);
        }
        for (int i = 0; i < n; i++) {
            node.add(i < m ? initFunc.apply(i) : monoid.identity());
            left[i + n] = i;
            right[i + n] = i + 1;
        }
        for (int i = n - 1; i > 0; i--) {
            node.set(i, monoid.merge(node.get(i * 2), node.get(i * 2 + 1)));
            left[i] = left[i * 2];
            right[i] = right[i * 2 + 1];
        }
        this.isBuilt = true;
    }

    void set(int i, T value) {
        i += n;
        node.set(i, value);
        while (i > 1) {
            i >>= 1;
            node.set(i, monoid.merge(node.get(i * 2), node.get(i * 2 + 1)));
        }
    }

    T get(int i) {
        return node.get(i + n);
    }

    T get(int l, int r) {
        l += n;
        r += n;
        T xl = monoid.identity();
        T xr = monoid.identity();
        while (l < r) {
            if (l % 2 == 1) {
                xl = monoid.merge(xl, node.get(l++));
            }
            if (r % 2 == 1) {
                xr = monoid.merge(node.get(--r), xr);
            }
            l >>= 1;
            r >>= 1;
        }
        return monoid.merge(xl, xr);
    }

    // check(get(0,index)) && !check(get(0,index+1)
    int binarySearchLeft(Predicate<T> predicate) {
        return binarySearchLeft(0, n, predicate);
    }

    int binarySearchLeft(int l, int r, Predicate<T> predicate) {
        T current = monoid.identity();
        for (int i = l + n; i < n * 2 && l < r;) {
            T t = monoid.merge(current, node.get(i));
            if (right[i] <= r && predicate.test(t)) {
                current = t;
                l = right[i];
                i++;
                if (i % 2 == 0) {
                    i >>= 1;
                }
            } else {
                i <<= 1;
            }
        }
        return l < r ? l : -1;
    }

    // !check(get(index-1,n)) && check(get(index,n)
    int binarySearchRight(Predicate<T> predicate) {
        return binarySearchRight(0, n, predicate);
    }

    int binarySearchRight(int l, int r, Predicate<T> predicate) {
        T current = monoid.identity();
        for (int i = r + n - 1; i < n * 2 && l < r;) {
            T t = monoid.merge(node.get(i), current);
            if (left[i] >= l && !predicate.test(t)) {
                current = t;
                r = left[i];
                i--;
                if (i % 2 == 1) {
                    i >>= 1;
                }
            } else {
                i = i * 2 + 1;
            }
        }
        return l < r ? r : -1;
    }

    List<T> getAll() {
        return new ArrayList<>(node.subList(n, n + m));
    }

    @Override
    public String toString() {
        return getAll().toString();
    }
}

class In {
