public void solve() {
	int num = ni();
	int query = ni();
	Long a[] = new Long[num];
	for(int i = 0; i < num; i ++) a[i] = nl();
	LazySegTree<Long> st = new LazySegTree<>(a,
			() -> -INF, (ele1, ele2) -> max(ele1, ele2),
			-INF, (ele1, ele2) -> ele2,
			(ele1, ele2) -> ele2);
	for(int q = 0; q < query; q ++) {
		int idx;
		switch(ni()) {
		case 1: idx = ni() - 1; st.update(idx, idx + 1, nl()); break;
		case 2: prtln(st.find(ni() - 1, ni())); break;
		case 3:
			idx = ni() - 1;
			long v = nl();
			int ans = st.findLeftmost(idx, (ele) -> ele >= v);
			prtln(ans < 0 ? num + 1 : ans + 1);
			break;
		}
	}
}

@FunctionalInterface
interface LazyFunction<T> { T apply(T t, long u); }
// interface LazyFunction<T, long> { T apply(T t, long u, int v); }
class LazySegTree<T> {
	Supplier<T> eSupplier;
	T e;
	BinaryOperator<T> f;
	long e2;
	LongBinaryOperator g;
	LazyFunction<T> h;

	int n;
	int height;
	T nodes[];
	long lazy[];
	int rangeL[];
	int rangeR[];

	LazySegTree(T[] a, Supplier<T> eSupplier, BinaryOperator<T> f, long e2, LongBinaryOperator g, LazyFunction<T> h) { init(a, eSupplier, f, e2, g, h); } // O(N)
	LazySegTree(int len, Supplier<T> xSupplier, Supplier<T> eSupplier, BinaryOperator<T> f, long e2, LongBinaryOperator g, LazyFunction<T> h) { // O(N)
		@SuppressWarnings("unchecked")
		T a[] = (T[]) new Object[len];
		for(int i = 0; i < len; i ++) a[i] = xSupplier.get();
		init(a, eSupplier, f, e2, g, h);
	}
	LazySegTree(int len, Supplier<T> eSupplier, BinaryOperator<T> f, long e2, LongBinaryOperator g, LazyFunction<T> h) { init(len, eSupplier, f, e2, g, h); } // O(N)

	void init(T[] a, Supplier<T> eSupplier, BinaryOperator<T> f, long e2, LongBinaryOperator g, LazyFunction<T> h) { // O(N)
		init(a.length, eSupplier, f, e2, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.apply(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, Supplier<T> eSupplier, BinaryOperator<T> f, long e2, LongBinaryOperator g, LazyFunction<T> h) { // O(N)
		this.eSupplier = eSupplier;
		this.e = e;
		this.f = f;
		this.e2 = e2;
		this.g = g;
		this.h = h;
		n = 1;
		height = 0;
		while(n < len) { n <<= 1; height ++; }
		@SuppressWarnings("unchecked")
		T tmp[] = (T[]) new Object[n << 1];
		this.nodes = tmp;
		for(int i = 0; i < nodes.length; i ++) nodes[i] = eSupplier.get();
		lazy = new long[n << 1];
		fill(lazy, e2);
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++)  { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.apply(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void eval(int k) { // O(1)
		if(lazy[k] != e2) {
			nodes[k] = h.apply(nodes[k], lazy[k]);
			// nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(k < n) {
				lazy[k << 1] = g.applyAsLong(lazy[k << 1], lazy[k]);
				lazy[(k << 1) + 1] = g.applyAsLong(lazy[(k << 1) + 1], lazy[k]);
			}
			lazy[k] = e2;
		}
	}

	void update(int l, int r, long val) { // O(logN)
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		int l0 = l;
		int r0 = r;
		r ++;
		while(l < r) {
			if((l & 1) != 0) { lazy[l] = g.applyAsLong(lazy[l], val); eval(l); l ++; }
			if((r & 1) != 0) { r --; lazy[r] = g.applyAsLong(lazy[r], val); eval(r); }
			l >>= 1; r >>= 1;
		}
		while(l0 > 1) {
			l0 >>= 1;
			nodes[l0] = f.apply(nodes[l0 << 1], nodes[(l0 << 1) + 1]);
		}
		while(r0 > 1) {
			r0 >>= 1;
			nodes[r0] = f.apply(nodes[r0 << 1], nodes[(r0 << 1) + 1]);
		}
	}

	T get(int i) { return find(i, i + 1); } // O(logN)
	T find(int l, int r) {
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		r ++;
		T xL = eSupplier.get();
		T xR = eSupplier.get();
		while(l < r) {
			if((l & 1) != 0) { eval(l); xL = f.apply(xL, nodes[l]); l ++; }
			if((r & 1) != 0) { r --; eval(r); xR = f.apply(nodes[r], xR); }
			l >>= 1; r >>= 1;
		}
		return f.apply(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(Predicate<T> check) { return findLeftmost(0, check); }
	int findLeftmost(int l, Predicate<T> check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, Predicate<T> check) {
		T crt = eSupplier.get();
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			eval(idx);
			T tmp = f.apply(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(Predicate<T> check) { return findRightmost(n, check); }
	int findRightmost(int r, Predicate<T> check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, Predicate<T> check) {
		T crt = eSupplier.get();
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			eval(idx);
			T tmp = f.apply(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

	}
}

