		Long[] A = new Long[N];
		for (int n = 0; n < N; n++) A[n] = sc.nextLong();

		SegTree<Long> seg = new SegTree<>(Math::max, () -> 1L, A);

		for (int q = 0; q < Q; q++) {
			int t = sc.nextInt();
			if (t == 1) {
				int x = sc.nextInt() - 1;
				long v = sc.nextLong();
				seg.set(x, v);
			} else if (t == 2) {
				int l = sc.nextInt() - 1;
				int r = sc.nextInt() - 1;
				System.out.println(seg.prod(l, r + 1));
			} else if (t == 3) {
				int x = sc.nextInt() - 1;
				long v = sc.nextLong();
				System.out.println(1 + seg.max_right(x, a -> a < v));
			}
		}
	}
}

