public void solve() {
	int num = ni();
	int query = ni();
	Long a[] = new Long[num];
	for(int i = 0; i < num; i ++) a[i] = nl();
	LazySegTree<Long, Tuple1<Long>> st = new LazySegTree<>(a,
			() -> -INF, (ele1, ele2) -> max(ele1, ele2),
			() -> new Tuple1<>(-INF), (ele1, ele2) -> ele1.a = ele2.a,
			(ele1, ele2) -> ele2.a);
	for(int q = 0; q < query; q ++) {
		int idx;
		switch(ni()) {
		case 1: idx = ni() - 1; st.update(idx, idx + 1, new Tuple1<>(nl())); break;
		case 2: prtln(st.find(ni() - 1, ni())); break;
		case 3:
			idx = ni() - 1;
			long v = nl();
			int ans = st.findLeftmost(idx, (ele) -> ele >= v);
			prtln(ans < 0 ? num + 1 : ans + 1);
			break;
		}
	}
}

@FunctionalInterface
interface BinaryConsumer<T> extends BiConsumer<T, T> {  }
@FunctionalInterface
interface LazyFunction<T, U> { T apply(T t, U u); }
// interface LazyFunction<T, U> { T apply(T t, U u, int v); }
class LazySegTree<T, U> {
	Supplier<T> eSupplier;
	T e;
	BinaryOperator<T> f;
	Supplier<U> e2Supplier;
	U e2;
	BinaryConsumer<U> g;
	LazyFunction<T, U> h;

	int n;
	T nodes[];
	U lazy[];

	LazySegTree(T[] a, Supplier<T> eSupplier, BinaryOperator<T> f, Supplier<U> e2Supplier, BinaryConsumer<U> g, LazyFunction<T, U> h) { init(a, eSupplier, f, e2Supplier, g, h); } // O(N)
	LazySegTree(int len, Supplier<T> xSupplier, Supplier<T> eSupplier, BinaryOperator<T> f, Supplier<U> e2Supplier, BinaryConsumer<U> g, LazyFunction<T, U> h) { // O(N)
		@SuppressWarnings("unchecked")
		T a[] = (T[]) new Object[len];
		for(int i = 0; i < len; i ++) a[i] = xSupplier.get();
		init(a, eSupplier, f, e2Supplier, g, h);
	}
	LazySegTree(int len, Supplier<T> eSupplier, BinaryOperator<T> f, Supplier<U> e2Supplier, BinaryConsumer<U> g, LazyFunction<T, U> h) { init(len, eSupplier, f, e2Supplier, g, h); } // O(N)

	void init(T[] a, Supplier<T> eSupplier, BinaryOperator<T> f, Supplier<U> e2Supplier, BinaryConsumer<U> g, LazyFunction<T, U> h) { // O(N)
		init(a.length, eSupplier, f, e2Supplier, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.apply(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, Supplier<T> eSupplier, BinaryOperator<T> f, Supplier<U> e2Supplier, BinaryConsumer<U> g, LazyFunction<T, U> h) { // O(N)
		this.eSupplier = eSupplier;
		this.e = eSupplier.get();
		this.f = f;
		this.e2Supplier = e2Supplier;
		this.e2 = e2Supplier.get();
		this.g = g;
		this.h = h;
		n = 1;
		while(n < len) n *= 2;
		@SuppressWarnings("unchecked")
		T tmp[] = (T[]) new Object[n * 2 - 1];
		this.nodes = tmp;
		for(int i = 0; i < nodes.length; i ++) nodes[i] = eSupplier.get();
		@SuppressWarnings("unchecked")
		U tmp2[] = (U[]) new Object[n * 2 - 1];
		lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2Supplier.get();
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.apply(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void eval(int k, int l, int r) { // O(1)
		if(!lazy[k].equals(e2)) {
			nodes[k] = h.apply(nodes[k], lazy[k]);
			// nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(r - l > 1) {
				g.accept(lazy[k * 2 + 1], lazy[k]);
				g.accept(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2Supplier.get();
		}
	}

	void update(int a, int b, U val) { update(a, b, val, 0, 0, n); } // O(logN)
	void update(int a, int b, U val, int k, int l, int r) { // O(logN)
		eval(k, l, r);
		if(b <= l || r <= a) return;
		if(a <= l && r <= b) {
			g.accept(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f.apply(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	T get(int i) { return find(i, i + 1); } // O(logN)
	T find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	T find(int a, int b, int k, int l, int r) { // O(logN)
		if(b <= l || r <= a) return e;
		eval(k, l, r);
		if(a <= l && r <= b) return nodes[k];
		return f.apply(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	T acc;
	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(Predicate<T> check) { return findLeftmost(0, check); }
	int findLeftmost(int a, Predicate<T> check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, Predicate<T> check) { acc = e; return findLeftmost(a, b, check, 0, 0, n); }
	int findLeftmost(int a, int b, Predicate<T> check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		T tmp = f.apply(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(Predicate<T> check) { return findRightmost(n, check); }
	int findRightmost(int b, Predicate<T> check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, Predicate<T> check) { acc = e; return findRightmost(a, b, check, 0, 0, n); }
	int findRightmost(int a, int b, Predicate<T> check, int k, int l, int r){
		eval(k, l, r);
		if(b <= l || r <= a) return -1;
		T tmp = f.apply(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, 2 * k + 1, l, (l + r) / 2);
	}
}

	}
}

import java.util.*;
import java.util.function.*;

class Internal {
	static int ceil_pow2(int n) {
		int x = 0;
		while ((1 << x) < n)
			x++;
		return x;
	}
}

class SegTree<S> {
	private final BinaryOperator<S> op;
	private final Supplier<S> e;

	private final int _n;
	private final int size;
	private final int log;
	private final ArrayList<S> d;

	public SegTree(BinaryOperator<S> op, Supplier<S> e, S[] v) {
		this.op = op;
		this.e = e;
		_n = v.length;
		log = Internal.ceil_pow2(_n);
		size = 1 << log;
		d = new ArrayList<>(2 * size);
		for (int i = 0; i < 2 * size; i++)
			d.add(e.get());
		for (int i = 0; i < _n; i++)
			d.set(size + i, v[i]);
		for (int i = size - 1; i >= 1; i--)
			update(i);
	}

	public SegTree(BinaryOperator<S> op, Supplier<S> e, List<S> v) {
		this.op = op;
		this.e = e;
		_n = v.size();
		log = Internal.ceil_pow2(_n);
		size = 1 << log;
		d = new ArrayList<>(2 * size);
		//このあとsetされるので2*sizeではなくsize
		for (int i = 0; i < size; i++)
			d.add(e.get());

		//定数時間accessでないListを考えてループ対象を変更
		int j = 0;
		for (S s : v) {
			d.set(size + j, s);
			j++;
		}

		for (int i = size - 1; i >= 1; i--)
			update(i);
	}

	public SegTree(BinaryOperator<S> op, Supplier<S> e, int n) {
		this.op = op;
		this.e = e;
		_n = n;
		log = Internal.ceil_pow2(_n);
		size = 1 << log;
		d = new ArrayList<>(2 * size);
		for (int i = 0; i < 2 * size; i++)
			d.add(e.get());
		for (int i = size - 1; i >= 1; i--)
			update(i);
	}

	public SegTree(BinaryOperator<S> op, Supplier<S> e) {
		this(op, e, 0);
	}

	public void set(int p, S x) {
		assert (0 <= p && p < _n);
		p += size;
		d.set(p, x);
		for (int i = 1; i <= log; i++)
			update(p >> i);
	}

	public S get(int p) {
		assert (0 <= p && p < _n);
		return d.get(p + size);
	}

	public S prod(int l, int r) {
		assert (0 <= l && l <= r && r <= _n);
		S sml = e.get(), smr = e.get();
		l += size;
		r += size;

		while (l < r) {
			if ((l & 1) > 0)
				sml = op.apply(sml, d.get(l++));
			if ((r & 1) > 0)
				smr = op.apply(d.get(--r), smr);
			l >>= 1;
			r >>= 1;
		}
		return op.apply(sml, smr);
	}

	public S all_prod() {
		return d.get(1);
	}

	public int max_right(int l, Predicate<S> f) {
		assert (0 <= l && l <= _n);
		assert (f.test(e.get()));
		if (l == _n)
			return _n;
		l += size;
		S sm = e.get();
		do {
			while (l % 2 == 0)
				l >>= 1;
			if (!f.test(op.apply(sm, d.get(l)))) {
				while (l < size) {
					l = 2 * l;
					if (f.test(op.apply(sm, d.get(l)))) {
						sm = op.apply(sm, d.get(l));
						l++;
					}
				}
				return l - size;
			}
			sm = op.apply(sm, d.get(l));
			l++;
		} while ((l & (-l)) != l);
		return _n;
	}

	public int min_left(int r, Predicate<S> f) {
		assert (0 <= r && r <= _n);
		assert (f.test(e.get()));
		if (r == 0)
			return 0;
		r += size;
		S sm = e.get();
		do {
			r--;
			while (r > 1 && (r % 2 > 0))
				r >>= 1;
			if (!f.test(op.apply(d.get(r), sm))) {
				while (r < size) {
					r = 2 * r + 1;
					if (f.test(op.apply(d.get(r), sm))) {
						sm = op.apply(d.get(r), sm);
						r--;
					}
				}
				return r + 1 - size;
			}
			sm = op.apply(d.get(r), sm);
		} while ((r & -r) != r);
		return 0;
	}

	private void update(int k) {
		d.set(k, op.apply(d.get(2 * k), d.get(2 * k + 1)));
	}
}

