public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	LazySegTree<Tuple1<Long>> st = new LazySegTree<>(a,
			-INF, (ele1, ele2) -> max(ele1, ele2),
			() -> new Tuple1<>(-INF), (ele1, ele2) -> ele1.a = ele2.a,
			(ele1, ele2) -> ele2.a);
	for(int q = 0; q < query; q ++) {
		int idx;
		switch(ni()) {
		case 1: idx = ni() - 1; st.update(idx, idx + 1, new Tuple1<>(nl())); break;
		case 2: prtln(st.find(ni() - 1, ni())); break;
		case 3:
			idx = ni() - 1;
			long v = nl();
			int ans = st.findLeftmost(idx, (ele) -> ele >= v);
			prtln(ans < 0 ? num + 1 : ans + 1);
			break;
		}
	}
}
