@FunctionalInterface
interface BinaryConsumer<T> extends BiConsumer<T, T> {  }
@FunctionalInterface
interface LazyFunction<T> { long apply(long t, T u); }
// interface LazyFunction<T> { long apply(long t, T u, int v); }
class LazySegTree<T> {
	long e;
	LongBinaryOperator f;
	Supplier<T> e2Supplier;
	T e2;
	BinaryConsumer<T> g;
	LazyFunction<T> h;

	int n;
	int height;
	long nodes[];
	T lazy[];
	int rangeL[];
	int rangeR[];

	LazySegTree(long[] a, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { init(a, e, f, e2Supplier, g, h); } // O(N)
	LazySegTree(int len, long x, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f, e2Supplier, g, h);
	}
	LazySegTree(int len, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { init(len, e, f, e2Supplier, g, h); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		init(a.length, e, f, e2Supplier, g, h);
		for(int i = 0; i < a.length; i ++) nodes[i + n] = a[i];
		for(int i = n - 1; i > 0; i --) nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
	}
	void init(int len, long e, LongBinaryOperator f, Supplier<T> e2Supplier, BinaryConsumer<T> g, LazyFunction<T> h) { // O(N)
		this.e = e;
		this.f = f;
		this.e2Supplier = e2Supplier;
		this.e2 = e2Supplier.get();
		this.g = g;
		this.h = h;
		n = 1;
		height = 0;
		while(n < len) { n <<= 1; height ++; }
		nodes = new long[n << 1];
		fill(nodes, e);
		@SuppressWarnings("unchecked")
		T tmp2[] = (T[]) new Object[n << 1];
		lazy = tmp2;
		for(int i = 0; i < lazy.length; i ++) lazy[i] = e2Supplier.get();
		rangeL = new int[n << 1];
		rangeR = new int[n << 1];
		for(int i = 0; i < n; i ++) { rangeL[i + n] = i; rangeR[i + n] = i + 1; }
		for(int i = n - 1; i > 0; i --) {
			nodes[i] = f.applyAsLong(nodes[i << 1], nodes[(i << 1) + 1]);
			rangeL[i] = rangeL[i << 1]; rangeR[i] = rangeR[(i << 1) + 1];
		}
	}

	void eval(int k) { // O(1)
		if(!lazy[k].equals(e2)) {
			nodes[k] = h.apply(nodes[k], lazy[k]);
			// nodes[k] = h.apply(nodes[k], lazy[k], r - l);
			if(k < n) {
				g.accept(lazy[k << 1], lazy[k]);
				g.accept(lazy[(k << 1) + 1], lazy[k]);
			}
			lazy[k] = e2Supplier.get();
		}
	}

	void update(int l, int r, T val) { // O(logN)
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		int l0 = l;
		int r0 = r;
		r ++;
		while(l < r) {
			if((l & 1) != 0) { g.accept(lazy[l], val); eval(l); l ++; }
			if((r & 1) != 0) { r --; g.accept(lazy[r], val); eval(r); }
			l >>= 1; r >>= 1;
		}
		while(l0 > 1) { l0 >>= 1; nodes[l0] = f.applyAsLong(nodes[l0 << 1], nodes[(l0 << 1) + 1]); }
		while(r0 > 1) { r0 >>= 1; nodes[r0] = f.applyAsLong(nodes[r0 << 1], nodes[(r0 << 1) + 1]); }
	}

	long get(int i) { return find(i, i + 1); } // O(logN)
	long find(int l, int r) {
		l += n; r += n - 1;
		for(int i = height; i > 0; i --) { eval(l >> i); eval(r >> i); }
		r ++;
		long xL = e;
		long xR = e;
		while(l < r) {
			if((l & 1) != 0) { eval(l); xL = f.applyAsLong(xL, nodes[l]); l ++; }
			if((r & 1) != 0) { r --; eval(r); xR = f.applyAsLong(nodes[r], xR); }
			l >>= 1; r >>= 1;
		}
		return f.applyAsLong(xL, xR);
	}

	// O(logN)
	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int l, LongPredicate check) { return findLeftmost(l, n, check); }
	int findLeftmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = l + n; idx < n << 1 && l < r; ){
			eval(idx);
			long tmp = f.applyAsLong(crt, nodes[idx]);
			if(rangeR[idx] <= r && !check.test(tmp)) {
				crt = tmp;
				l = rangeR[idx ++];
				if((idx & 1) == 0) idx >>= 1;
			}else idx <<= 1;
		}
		return l >= r ? -1 : l;
	}
	// O(logN)
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int r, LongPredicate check) { return findRightmost(0, r, check); }
	int findRightmost(int l, int r, LongPredicate check) {
		long crt = e;
		int idx;
		for(idx = r + n - 1; idx < n << 1 && r > l; ){
			eval(idx);
			long tmp = f.applyAsLong(nodes[idx], crt);
			if(rangeL[idx] >= l && !check.test(tmp)) {
				crt = tmp;
				r = rangeL[idx --];
				if((idx & 1) != 0) idx >>= 1;
			}else idx = (idx << 1) + 1;
		}
		return r <= l ? -1 : r;
	}
}

	}
}

import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Scanner;
import java.util.function.BinaryOperator;
import java.util.function.Predicate;

public class Main {
    public static void main(String[] args) {
        var sc = new Scanner(System.in);
        var pw = new PrintWriter(System.out);
        final int N = Integer.parseInt(sc.next());
        final int Q = Integer.parseInt(sc.next());
        final var A = new Integer[N];
        Arrays.setAll(A, i -> Integer.parseInt(sc.next()));
        var t = new SegTree<Integer>(A, -1, Integer::max);
        for (int $ = 0; $ < Q; $++) {
            int query = Integer.parseInt(sc.next());
            int a = Integer.parseInt(sc.next()) - 1;
            int b = Integer.parseInt(sc.next());
            switch (query) {
                case 1:
                    t.set(a, b);
                    break;
                case 2:
                    pw.println(t.prod(a, b));
                    break;
                case 3:
                    pw.println(t.maxRight(a, x -> x < b) + 1);
                    break;
                default:
                    break;
            }
        }
        sc.close();
        pw.flush();
        pw.close();
    }
}

class SegTree<S> {
    final int MAX;

    final int N;
    final S E;
    final BinaryOperator<S> Op;

    final S[] Dat;

    @SuppressWarnings("unchecked")
    public SegTree(int n, S e, BinaryOperator<S> op) {
        this.MAX = n;
        int k = 1;
        while (k < n) k <<= 1;
        this.N = k;
        this.E = e;
        this.Op = op;
        this.Dat = (S[]) new Object[N << 1];
        Arrays.fill(Dat, E);
    }

    public SegTree(S[] dat, S e, BinaryOperator<S> op) {
        this(dat.length, e, op);
        build(dat);
    }

    private void build(S[] dat) {
        int l = dat.length;
        System.arraycopy(dat, 0, Dat, N, l);
        for (int i = N - 1; i > 0; i--) {
            Dat[i] = Op.apply(Dat[i << 1 | 0], Dat[i << 1 | 1]);
        }
    }

    public void set(int p, S x) {
        exclusiveRangeCheck(p);
        Dat[p += N] = x;
        p >>= 1;
        while (p > 0) {
            Dat[p] = Op.apply(Dat[p << 1 | 0], Dat[p << 1 | 1]);
            p >>= 1;
        }
    }

    public S get(int p) {
        exclusiveRangeCheck(p);
        return Dat[p + N];
    }

    public S prod(int l, int r) {
        if (l > r) {
            throw new IllegalArgumentException("TODO");
        }
        inclusiveRangeCheck(l);
        inclusiveRangeCheck(r);
        S sumLeft = E;
        S sumRight = E;
        l += N; r += N;
        while (l < r) {
            if ((l & 1) == 1) sumLeft = Op.apply(sumLeft, Dat[l++]);
            if ((r & 1) == 1) sumRight = Op.apply(Dat[--r], sumRight);
            l >>= 1; r >>= 1;
        }
        return Op.apply(sumLeft, sumRight);
    }

    public S allProd() {
        return Dat[1];
    }

    public int maxRight(int l, Predicate<S> f) {
        inclusiveRangeCheck(l);
        if (!f.test(E)) {
            throw new IllegalArgumentException("TODO");
        }
        if (l == MAX) return MAX;
        l += N;
        S sum = E;
        do {
            l >>= Integer.numberOfTrailingZeros(l);
            if (!f.test(Op.apply(sum, Dat[l]))) {
                while (l < N) {
                    l = l << 1;
                    if (f.test(Op.apply(sum, Dat[l]))) {
                        sum = Op.apply(sum, Dat[l]);
                        l++;
                    }
                }
                return l - N;
            }
            sum = Op.apply(sum, Dat[l]);
            l++;
        } while ((l & -l) != l);
        return MAX;
    }

    public int minLeft(int r, Predicate<S> f) {
        inclusiveRangeCheck(r);
        if (!f.test(E)) {
            throw new IllegalArgumentException("TODO");
        }
        if (r == 0) return 0;
        r += N;
        S sum = E;
        do {
            r--;
            while (r > 1 && (r & 1) == 1) r >>= 1;
            if (!f.test(Op.apply(Dat[r], sum))) {
                while (r < N) {
                    r = r << 1 | 1;
                    if (f.test(Op.apply(Dat[r], sum))) {
                        sum = Op.apply(Dat[r], sum);
                        r--;
                    }
                }
                return r + 1 - N;
            }
            sum = Op.apply(Dat[r], sum);
        } while ((r & -r) != r);
        return 0;
    }

    private void exclusiveRangeCheck(int p) {
        if (p < 0 || p >= MAX) {
            throw new IndexOutOfBoundsException(
                "TODO"
            );
        }
    }

    private void inclusiveRangeCheck(int p) {
        if (p < 0 || p > MAX) {
            throw new IndexOutOfBoundsException(
                "TODO"
            );
        }
    }
}

