public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	SegTree st = new SegTree(a,
			0, (ele1, ele2) -> max(ele1, ele2));
	for(int q = 0; q < query; q ++) {
		switch(ni()) {
		case 1: st.set(ni() - 1, nl()); break;
		case 2: prtln(st.find(ni() - 1, ni())); break;
		case 3:
			int idx = ni() - 1;
			long v = nl();
			int ans = st.findLeftmost(idx, (long ele) -> ele >= v);
			prtln(ans < 0 ? num + 1 : ans + 1);
			break;
		}
	}
}

class SegTree {
	long e;
	LongBinaryOperator f;

	int n;
	long nodes[];

	SegTree(long[] a, long e, LongBinaryOperator f) { init(a, e, f); } // O(N)
	SegTree(int len, long x, long e, LongBinaryOperator f) { // O(N)
		long a[] = new long[len];
		fill(a, x);
		init(a, e, f);
	}
	SegTree(int len, long e, LongBinaryOperator f) { init(len, e, f); } // O(N)

	void init(long[] a, long e, LongBinaryOperator f) { // O(N)
		init(a.length, e, f);
		for(int i = 0; i < a.length; i ++) nodes[i + n - 1] = a[i];
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}
	void init(int len, long e, LongBinaryOperator f) { // O(N)
		this.e = e;
		this.f = f;
		n = 1;
		while(n < len) n *= 2;
		nodes = new long[n * 2 - 1];
		fill(nodes, e);
		for(int i = n - 2; i >= 0; i --) nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
	}

	void set(int i, long val) { // O(logN)
		i += n - 1;
		nodes[i] = val;
		while(i > 0) {
			i = (i - 1) / 2;
			nodes[i] = f.applyAsLong(nodes[i * 2 + 1], nodes[i * 2 + 2]);
		}
	}
	void update(int i, long val) { set(i, f.applyAsLong(nodes[i + n - 1], val)); } // O(logN)

	long get(int i) { return find(i, i + 1); } // O(logN)

	long find(int a, int b) { return find(a, b, 0, 0, n); } // O(logN)
	long find(int a, int b, int k, int l, int r) { // O(logN)
		if(b <= l || r <= a) return e;
		if(a <= l && r <= b) return nodes[k];
		return f.applyAsLong(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}

	long acc;

	// min idx s.t. a<=idx<b && !check(find(a,idx)) && check(find(a,idx+1))
	int findLeftmost(LongPredicate check) { return findLeftmost(0, check); }
	int findLeftmost(int a, LongPredicate check) { return findLeftmost(a, n, check); }
	int findLeftmost(int a, int b, LongPredicate check) { acc = e; return findLeftmost(a, b, check, e, 0, 0, n); }
	int findLeftmost(int a, int b, LongPredicate check, long acc, int k, int l, int r){
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findLeftmost(a, b, check, acc, 2 * k + 1, l, (l + r) / 2);
		return vr >= 0 ? vr : findLeftmost(a, b, check, acc, 2 * k + 2, (l + r) / 2, r);
	}
	// max idx s.t. a<=idx<b && !check(find(idx,b)) && check(find(idx+1,b))
	int findRightmost(LongPredicate check) { return findRightmost(n, check); }
	int findRightmost(int b, LongPredicate check) { return findRightmost(0, b, check); }
	int findRightmost(int a, int b, LongPredicate check) { acc = e; return findRightmost(a, b, check, e, 0, 0, n); }
	int findRightmost(int a, int b, LongPredicate check, long acc, int k, int l, int r){
		if(b <= l || r <= a) return -1;
		long tmp = f.applyAsLong(acc, nodes[k]);
		if(!check.test(tmp)) { acc = tmp; return -1; }
		if(l + 1 == r) { acc = tmp; return k - n + 1; }
		int vr = findRightmost(a, b, check, acc, 2 * k + 2, (l + r) / 2, r);
		return vr >= 0 ? vr : findRightmost(a, b, check, acc, 2 * k + 1, l, (l + r) / 2);
	}
