public class Program
{

    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int q = sc.NextInt();
        int[] a = sc.IntArray();
        var lst = new LazySegmentTree<int, (int num, bool f)>(a, Math.Max, int.MinValue, (f, x) => f.f ? f.num : x, (f, g) => f.f ? f : g, (-1, false));

        Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
        for (int i = 0; i < q; i++)
        {
            int t = sc.NextInt();

            if (t == 1)
            {
                int x = sc.NextInt() - 1;
                int v = sc.NextInt();
                lst.Set(x, v);
            }
            else if (t == 2)
            {
