using CompLib.Collections.Generic;
using CompLib.Util;
using System;

public class Program
{

    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();
        int q = sc.NextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
        {
            a[n - i - 1] = sc.NextInt();
        }
        var st = new SegmentTree<int>(a, Math.Max, int.MinValue);

        Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
        for (int i = 0; i < q; i++)
        {
            int t = sc.NextInt();
            if (t == 1)
            {
                int x = sc.NextInt() - 1;
                int v = sc.NextInt();
                st[n - x - 1] = v;
            }
            if (t == 2)
            {
                int l = n - sc.NextInt() + 1;
                int r = n - sc.NextInt();
                Console.WriteLine(st.Query(r, l));
            }
            if (t == 3)
            {
                int x = n - sc.NextInt() + 1;
                int v = sc.NextInt();
                int j = st.MinLeft(x, num => v > num);
                Console.WriteLine(n - j + 1);
            }
        }
        Console.Out.Flush();
    }

    public static void Main(string[] args) => new Program().Solve();
