        _node = new TMonoid[2 * Count];

        for (int i = 0; i < n; i++) {
            _node[i + Count] = create(i);
        }

        for (int i = Count - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
        }
    }

    public void Set(int index, TMonoid val) {
        int p = index + Count;
        _node[p] = val;
        while (p > 0) {
            p >>= 1;
            _node[p] = _merge(_node[p << 1], _node[p << 1 | 1]);
        }
    }

    public TMonoid Query(int begin, int end) {
        TMonoid lv = _identity, rv = _identity;
        int l = begin + Count;
        int r = end + Count - 1;
        for (; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lv = _merge(lv, _node[l++]); }
            if ((r & 1) == 0) { rv = _merge(_node[r--], rv); }
        }
        return _merge(lv, rv);
    }

    public int MaxRight(int l, Predicate<TMonoid> f) {
        if (l == Count) return Count;
        l += Count;
        var sm = _identity;
        var x = Count;
        var set = new HashSet<int>();
        while (x > 0) {
            set.Add(x);
            x >>= 1;
        }
        do {
            while (l % 2 == 0) l >>= 1;
            if (!f(_merge(sm, _node[l]))) {
                while (l < Count) {
                    l = (2 * l);
                    if (f(_merge(sm, _node[l]))) {
                        sm = _merge(sm, _node[l]);
                        l++;
                    }
                }
                return l - Count;
            }
            sm = _merge(sm, _node[l]);
            l++;
        } while (!set.Contains(l));
        return Count;
    }
    public int MinLeft(int r, Predicate<TMonoid> f) {
