public sealed class SegmentTree<TMonoid> {
    public int Count { get; private set; }
    private int _power2Size;
    private TMonoid[] _node;
    private readonly TMonoid _identity;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;

    public SegmentTree(Func<TMonoid, TMonoid, TMonoid> merge, TMonoid identity) {
        _merge = merge;
        _identity = identity;
    }

    public void Build(IList<TMonoid> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, TMonoid> create) {
        Count = n;
        _power2Size = 1;
        while (_power2Size < n) _power2Size <<= 1;

        _node = new TMonoid[2 * _power2Size];

        for (int i = 0; i < _power2Size; i++) {
            _node[i + _power2Size] = (i < n) ? create(i) : _identity;
        }

        for (int i = _power2Size - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
        }
    }

    public void Set(int index, TMonoid val) {
        int p = index + _power2Size;
        _node[p] = val;
        while (p > 0) {
            p >>= 1;
            _node[p] = _merge(_node[p << 1], _node[p << 1 | 1]);
        }
    }

    public TMonoid Query(int begin, int end) {
        TMonoid lv = _identity, rv = _identity;
        int l = begin + _power2Size;
        int r = end + _power2Size - 1;
        for (; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { lv = _merge(lv, _node[l++]); }
            if ((r & 1) == 0) { rv = _merge(_node[r--], rv); }
        }
        return _merge(lv, rv);
    }

    public int MaxRight(int l, Predicate<TMonoid> f) {
        if (l == Count) return Count;
        l += _power2Size;
        var sm = _identity;
        do {
            while (l % 2 == 0) l >>= 1;
            if (!f(_merge(sm, _node[l]))) {
                while (l < _power2Size) {
                    l <<= 1;
                    var x = _merge(sm, _node[l]);
                    if (f(x)) {
                        sm = x;
                        l++;
                    }
                }
                return l - _power2Size;
            }
            sm = _merge(sm, _node[l]);
            l++;
        } while ((l & -l) != l);
        return Count;
    }

    public TMonoid this[int index] {
        get { return _node[index + _power2Size]; }
        set { Set(index, value); }
    }
};
