			P<ll,ll,ll>[] t;
			rl(q,out t);

			SegmentTree<ll> seg = new SegmentTree<ll>(n,Max,0);
			for (int i = 0; i < n; i++)
			{
				seg.Update(i,a[i]);
			}

			List<ll> ans = new List<ll>();
			foreach (var e in t)
			{
				if(e.A==1){
					seg.Update(e.B-1,e.C);
				}
				if(e.A==2){
					ans.Add(seg.Query(e.B-1,e.C));
				}
				if(e.A==3){
					Func<ll,ll> f = (x)=>(e.C<=seg.Query(e.B-1,x)?1:0);
					ans.Add(BS(f,1,e.B-1,n+1));
				}
			}

			Lib_IO.wl(ans);
		}
	}

	public static long BS<T>(Func<long,T> seq, T value, long ileft, long iright)  where T : IComparable<T> {
		long left = ileft;
		long right = iright;
		while (right - left > 1) {
			long mid = left + (right - left) / 2;
			if (0<=seq(mid).CompareTo(value)) right = mid;
			else left = mid;
		}
		return right;
	}
public class SegmentTree<TM> {
	private int sz;
	private TM[] data;
	private Func<TM,TM,TM> f;
	private TM M1;

	public SegmentTree(long n, Func<TM,TM,TM> f, TM M1) {
		this.f = f;
		this.M1 = M1;
		sz = 1;
		while(sz < n) sz <<= 1;
		data = Enumerable.Repeat(M1, 2 * sz).ToArray();
	}
	public TM this[long k] {
		get { return data[k + sz - 1]; }
		set { data[k + sz - 1] = value; }
	}
	public void Build() {
		for(int k = sz - 2; k >= 0; k--) data[k] = f(data[2 * k + 1], data[2 * k + 2]);
	}
	public void Update(long k, TM x) {
		k += sz - 1;
		data[k] = x;
        while (k > 0) {
            k = (k - 1) / 2;  // parent
            data[k] = f(data[k * 2 + 1], data[k * 2 + 2]);
        }
	}
	private TM Query(long a, long b, int k, int l, int r) {
        if (r <= a || b <= l) {
            return M1;
        } else if (a <= l && r <= b) {
            return data[k];
        } else {
            TM vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
            TM vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
            return f(vl, vr);
        }
	}
    public TM Query(long a, long b) { return Query(a, b, 0, 0, sz); }


}












