public class SegmentTree<T>
{
    protected readonly T[] dat;
    protected readonly int _N,sz;
    protected readonly Func<T, T, T> merge;
    protected readonly Func<T, T, T> update;
    protected readonly T id;
    private bool finished = true;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    protected int Left(int i)
        => i << 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    protected int Right(int i)
        => (i << 1) | 1;
    public T this[int i]
    {
        get { return dat[i + sz]; }
        set { finished = false; dat[i + sz] = value; }
    }

    public SegmentTree(int N, T id, Func<T, T, T> merge, Func<T, T, T> update = null)
    {
        _N = N;
        this.sz = 1;
        while (sz < N) sz <<= 1;
        this.id = id;
        this.merge = merge;
        this.update = update ?? ((T val1, T val2) => val2);
        dat = Create(sz << 1, () => id);
    }

    public void Update(int i, T value)
    {
        i += sz;
        dat[i] = update(dat[i], value);
        while (i > 1)
        {
            i >>= 1;
            dat[i] = merge(dat[Left(i)], dat[Right(i)]);
        }
    }

    public void Build()
    {
        for (int i = sz - 1; i > 0; i--)
            dat[i] = merge(dat[Left(i)], dat[Right(i)]);
        finished = true;
    }

    public virtual T Query(int left, int right)
    {
        if (!finished) throw new Exception("You need to Execute \"Build()\"");
        T l = id, r = id;
        for (left += sz, right += sz; left < right; left >>= 1, right >>= 1)
        {
            if ((left & 1) == 1) l = merge(l, dat[left++]);
            if ((right & 1) == 1) r = merge(dat[--right], r);
        }
        return merge(l, r);
    }
    public int MaxRight(int l,Func<T,bool> f)
    {
        if (l == _N) return _N;
        l += sz;
        var sm = id;
        do
        {
            while ((l & 1) == 0) l >>= 1;
            if (!f(merge(sm, dat[l])))
            {
                while (l < sz)
                {
                    l <<= 1;
                    if (f(merge(sm, dat[l])))
                    {
                        sm = merge(sm, dat[l]);
                        l++;
                    }
                }
                return l - sz;
            }
            sm = merge(sm, dat[l]);
            l++;
        } while ((l & -l) != l);
        return _N;
    }
    public int MinLeft(int r, Func<T, bool> f)
    {
        if (r == 0) return 0;
        r += sz;
        var sm = id;
        do
        {
            r--;
            while (r > 1 && (r & 1) == 1) r >>= 1;
            if (!f(merge(dat[r], sm)))
            {
                while (r < sz)
                {
                    r = (r << 1) | 1;
                    if (f(merge(dat[r], sm)))
                    {
                        sm = merge(dat[r], sm); r--;
                    }
                }
                return r + 1 - sz;
            }
            sm = merge(dat[r], sm);
        } while ((r & -r) != r);
        return 0;
    }
}

public class FastScanner
{
    //0x0a:LF 0x20:SPC 0x2d:- 0x30 ~ 0x39: 0 ~ 9
    static System.IO.Stream str = System.Console.OpenStandardInput();
    const int size = 1 << 10;
    static byte[] buffer = new byte[size];
    static int ptr;
    static int len;
    public int Int
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    public long Long
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0L;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    byte Read()
    {
        if (ptr == len)
        {
            len = str.Read(buffer, 0, size);
            if (len == 0) return 0;
            ptr = 0;
        }
        return buffer[ptr++];
    }
}
