	s.d[i] = a
	for i >>= 1; i > 0; i >>= 1 {
		s.d[i] = s.f(s.d[2*i], s.d[2*i+1])
	}
}

func (s *segmentTree) query(l, r int) node {
	vl, vr := s.e, s.e
	l += s.sz
	r += s.sz
	for l < r {
		if l&1 == 1 {
			vl = s.f(vl, s.d[l])
			l++
		}
		if r&1 == 1 {
			r--
			vr = s.f(s.d[r], vr)
