}

func (seg segmentTree) build(d []int) {
	for i := 0; i < len(d); i++ {
		seg.d[i+seg.sz] = d[i]
	}
	for i := seg.sz - 1; i > 0; i-- {
		seg.d[i] = seg.op(seg.d[2*i], seg.d[2*i+1])
	}
}

func (seg segmentTree) get(i int) int {
