                right_li.append(r)
            l >>= 1
            r >>= 1
        temp = self.id
        for idx in (left_li + right_li[::-1]):
            if not check(self.f(temp, self.data[idx])):
                temp = self.f(temp, self.data[idx])
            else:
                break
        else:
            return -1
        while idx < self.n:
            if check(self.f(temp, self.data[idx<<1])):
                idx = idx<<1
            else:
                temp = self.f(temp, self.data[idx<<1])
                idx = idx<<1|1
        return idx - self.n

    def min_left(self, l, r, check):
        l += self.n
        r += self.n
        left_li = []
        right_li = []
        while l < r:
            if l & 1:
                left_li.append(l)
                l += 1
            if r & 1:
                r -= 1
                right_li.append(r)
            l >>= 1
            r >>= 1
        temp = self.id
        for idx in (right_li + left_li[::-1]):
            if not check(self.f(self.data[idx], temp)):
                temp = self.f(self.data[idx], temp)
            else:
                break
        else:
            return -1
        while idx < self.n:
            if check(self.f(self.data[idx<<1|1], temp)):
                idx = idx<<1|1
            else:
                temp = self.f(temp, self.data[idx<<1|1], temp)
