class Seg_Tree:
  def __init__(self,init_list,init_value,func=min):
    il_len=len(init_list)
    r=1
    while il_len>r:
      r*=2
    self.tree=[0 for i in range(r-1)]+copy(init_list)+[init_value for i in range(r-il_len)]
    self.func=func
    self.len=r
    self.init_value=init_value
    for i in range(r-2,-1,-1):
      self.tree[i]=self.func(self.tree[i*2+1],self.tree[i*2+2])

  def update(self,x,value):
    x+=self.len-1
    self.tree[x]=value
    x=(x-1)//2
    while x>=0:
      self.tree[x]=self.func(self.tree[x*2+1],self.tree[x*2+2])
      x=(x-1)//2

  def query(self,l,r,x=0):
    xl=x
    xr=x
    while xl<self.len-1:
      xl,xr=xl*2+1,xr*2+2
    if xr<l+self.len-1 or r+self.len-1<xl:
      return self.init_value
    elif l+self.len-1<=xl and xr<=r+self.len-1:
      return self.tree[x]
    else:
      return self.func(self.query(l,r,x*2+1),self.query(l,r,x*2+2))


