def bis_min(node,l,r,cond):
  x,y=l,r
  z=node[-1]-1
  for i in range(30):
    if x+(1<<i)>y:
      break
    if x&(1<<i):
      if cond(node[z+(x>>i)]):
        return bis_min_k(node,z+(x>>i),cond)
      x+=(1<<i)
    if z==0:
      break
    z>>=1
  for i in range(29,-1,-1):
    if i and (node[-1]>>(i-1))==0:
      continue
    if x+(1<<i)>y:
      continue
    if x&(1<<i):
      if cond(node[(node[-1]>>i)+(x>>i)]):
        return bis_min_k(node,(node[-1]>>i)+(x>>i),cond)
      x+=(1<<i)
  return node[-1]

