pub trait TE {
    type T: Clone;
    type E: Clone;
    fn fold(l: Self::T, r: Self::T) -> Self::T;
    fn eval(p: Self::T, x: Self::E) -> Self::T;
    fn merge(f: Self::E, g: Self::E) -> Self::E;
    fn e() -> Self::T;
    fn id() -> Self::E;
}

pub struct LazySegmentTree<R: TE> {
    size: usize,
    bit: usize,
    a: Vec<(R::T, R::E)>,
}

impl <R: TE> LazySegmentTree<R> {
    pub fn new(n: usize) -> LazySegmentTree<R> {
        let mut bit = 0;
        while (1 << bit) < n {
            bit += 1;
        }
        LazySegmentTree {
            size: 1 << bit,
            bit: bit,
            a: vec![(R::e(), R::id()); 2 << bit],
        }
    }
    pub fn build_by(z: &[R::T]) -> LazySegmentTree<R> {
        let n = z.len();
        let mut bit = 0;
        while (1 << bit) < n {
            bit += 1;
        }
        let mut a = vec![(R::e(), R::id()); 2 << bit];
        for (a, z) in a[(1 << bit)..].iter_mut().zip(z.iter()) {
            a.0 = z.clone();
        }
        for i in (1..(1 << bit)).rev() {
            let l = R::eval(a[2 * i].0.clone(), a[2 * i].1.clone());
            let r = R::eval(a[2 * i + 1].0.clone(), a[2 * i + 1].1.clone());
            a[i].0 = R::fold(l, r);
        }
        LazySegmentTree {
            size: 1 << bit,
            bit : bit,
            a: a,
        }
    }
    fn eval(&self, k: usize) -> R::T {
        R::eval(self.a[k].0.clone(), self.a[k].1.clone())
    }
    fn propagate(&mut self, x: usize) {
        let x = x + self.size;
        for i in (1..(self.bit + 1)).rev() {
            let k = x >> i;
            self.a[2 * k].1 = R::merge(self.a[2 * k].1.clone(), self.a[k].1.clone());
            self.a[2 * k + 1].1 = R::merge(self.a[2 * k + 1].1.clone(), self.a[k].1.clone());
            self.a[k].1 = R::id();
            self.a[k].0 = R::fold(self.eval(2 * k), self.eval(2 * k + 1));
        }
    }
    fn save(&mut self, x: usize) {
        let x = x + self.size;
        for i in 1..(self.bit + 1) {
            let k = x >> i;
            self.a[k].0 = R::fold(self.eval(2 * k), self.eval(2 * k + 1));
        }
    }
    pub fn update(&mut self, l: usize, r: usize, op: R::E) {
        self.propagate(l);
        self.propagate(r - 1);
        let mut x = l + self.size;
        let mut y = r + self.size;
        while x < y {
            if x & 1 == 1 {
                self.a[x].1 = R::merge(self.a[x].1.clone(), op.clone());
                x += 1;
            }
            if y & 1 == 1 {
                y -= 1;
                self.a[y].1 = R::merge(self.a[y].1.clone(), op.clone());
            }
            x >>= 1;
            y >>= 1;
        }
        self.save(l);
        self.save(r - 1);
    }
    pub fn find(&mut self, l: usize, r: usize) -> R::T {
        self.propagate(l);
        self.propagate(r - 1);
        let mut x = l + self.size;
        let mut y = r + self.size;
        let mut p = R::e();
        let mut q = R::e();
        while x < y {
            if x & 1 == 1 {
                p = R::fold(p, self.eval(x));
                x += 1;
            }
            if y & 1 == 1 {
                y -= 1;
                q = R::fold(self.eval(y), q);
            }
            x >>= 1;
            y >>= 1;
        }
        R::fold(p, q)
    }
}

struct R;
impl TE for R {
    type T = (i64,usize);
    type E = i64;
    fn fold(l: Self::T, r: Self::T) -> Self::T {
        max(l,r)
    }
    fn eval(p: Self::T, x: Self::E) -> Self::T {
        if x!=INF {
            (x,p.1)
        }
        else {
            p
        }
    }
    fn merge(f: Self::E, g: Self::E) -> Self::E {
        if g==INF {
            f
        }
        else {
            g
        }
    }
    fn e() -> Self::T {
        (0, 0)
    }
    fn id() -> Self::E {
        INF
    }
}

fn solve() {
    let (n,q) = read!(usize,usize);
    let a = read!([i64]);
    let txy = read!(usize,usize,usize;q);

    let v = a.iter().enumerate().map(|x| (*x.1,x.0)).collect::<Vec<(i64,usize)>>();
    let mut seg = LazySegmentTree::<R>::build_by(v.as_slice());

    for (t,x,y) in txy {
        if t==1 {
            seg.update(x-1,x,y as i64);
        }
        if t==2 {
            let ans = seg.find(x-1,y);
            println!("{}",ans.0);
        }
        if t==3 {
            let mut left = x-1;
            let mut right = n;
            while right-left>1 {
                let mid = (left+right)/2;
                let ret = seg.find(x-1,mid+1);
                if ret.0>=y as i64{
                    right = mid;
                }
                else {
                    left = mid;
                }
            }
            if seg.find(x-1,x).0>=y as i64 {
                println!("{}",x);
            }
            else{
                println!("{}",right+1);
            }
        }
    }
}

fn run() {
    solve();
}

