struct SegmentTree<T: Copy> {
    n: usize,
    f: fn(T, T) -> T,
    e: T,
    binary_tree: Vec<T>,
}
impl<T: Copy> SegmentTree<T> {
    /// O(n) # create segment tree (e is identity element for a function f in type T)
    fn new(data: &[T], e: T, f: fn(T, T) -> T) -> Self {
        let (n, binary_tree) = (data.len(), vec![e; 2 * data.len().next_power_of_two() - 1]);
        let segment_tree = SegmentTree {
            n,
            f,
            e,
            binary_tree,
        };
        segment_tree.init(data)
    }

    /// O(n) # init segment tree by given data
    fn init(mut self, data: &[T]) -> Self {
        let leaf_offset = self.leaf_offset();
        for (i, &di) in data.iter().enumerate() {
            self.binary_tree[leaf_offset + i] = di;
        }
        for i in (0..leaf_offset).rev() {
            self.binary_tree[i] = (self.f)(
                self.binary_tree[Self::left_child(i)],
                self.binary_tree[Self::right_child(i)],
            );
        }
        self
    }

    /// O(1) # get beginning index of the segment tree leaf
    fn leaf_offset(&self) -> usize {
        self.n.next_power_of_two() - 1
    }

    /// O(1) # get size of leaves
    fn num_of_leaf(&self) -> usize {
        self.n.next_power_of_two()
    }

    /// O(1) # get left child index of node x
    fn left_child(x: usize) -> usize {
        x * 2 + 1
    }

    /// O(1) # get right child index of node x
    fn right_child(x: usize) -> usize {
        x * 2 + 2
    }

    /// O(1) # get parent index of node x
    fn parent(x: usize) -> usize {
        (x - 1) / 2
    }

    /// O(1) # get root index
    fn root() -> usize {
        0
    }

    /// O(1) # either node x is root or not
    fn is_root(x: usize) -> bool {
        x == Self::root()
    }

    /// O(log(n)) # update segment tree, leaf[k] = x
    fn update(&mut self, k: usize, x: T) {
        let i = self.leaf_offset() + k;
        self.binary_tree[i] = x;
        self.recursive_update(Self::parent(i));
    }

    /// O(log(i)) # update from leaf to root
    fn recursive_update(&mut self, i: usize) {
        if !Self::is_root(i) {
            self.binary_tree[i] = (self.f)(
                self.binary_tree[Self::left_child(i)],
                self.binary_tree[Self::right_child(i)],
            );
            self.recursive_update(Self::parent(i));
        }
    }

    /// O(log(n)) # calculate half-open interval summation from l to r (leaf index)
    fn query(&self, l: usize, r: usize) -> T {
        self.recursive_query(l, r, Self::root(), 0, self.num_of_leaf())
    }

    /// O(log(n)-log(node)) # calculate summation from root to leaf
    fn recursive_query(&self, l: usize, r: usize, node: usize, from: usize, to: usize) -> T {
        if r <= from || to <= l {
            self.e
        } else if l <= from && to <= r {
            self.binary_tree[node]
        } else {
            let mid = (from + to) / 2;
            (self.f)(
                self.recursive_query(l, r, Self::left_child(node), from, mid),
                self.recursive_query(l, r, Self::right_child(node), mid, to),
            )
        }
    }

    fn min_left<F>(&self, l: usize, f: F) -> Option<usize>
    where
        F: Fn(T) -> bool,
    {
        self.recursive_min_left(l, f, Self::root(), 0, self.num_of_leaf())
    }

    fn recursive_min_left<F>(
        &self,
        l: usize,
        f: F,
        node: usize,
        from: usize,
        to: usize,
    ) -> Option<usize>
    where
        F: Fn(T) -> bool,
    {
        if to <= l {
            None
        } else if to - from <= 1 {
            if f(self.binary_tree[node]) {
                Some(node - self.leaf_offset())
            } else {
                None
            }
        } else {
            let mid = (from + to) / 2;
            if f(self.binary_tree[Self::left_child(node)]) {
                self.recursive_min_left(l, f, Self::left_child(node), from, mid)
            } else if f(self.binary_tree[Self::right_child(node)]) {
                self.recursive_min_left(l, f, Self::right_child(node), mid, to)
            } else {
                None
            }
        }
    }
}

//---------- begin SegmentTree Point update Range query ----------
pub trait PURQ {
    type T: Clone;
    fn fold(l: &Self::T, r: &Self::T) -> Self::T;
    fn e() -> Self::T;
}

struct SegmentTreePURQ<R: PURQ> {
    seg: Vec<R::T>,
    size: usize,
}

#[allow(dead_code)]
impl<R: PURQ> SegmentTreePURQ<R> {
    fn new(n: usize) -> SegmentTreePURQ<R> {
        let size = n.next_power_of_two();
        SegmentTreePURQ {
            seg: vec![R::e(); 2 * size],
            size: size,
        }
    }
    fn build_by(a: &[R::T]) -> SegmentTreePURQ<R> {
        let size = a.len().next_power_of_two();
        let mut b = vec![R::e(); 2 * size];
        for i in 0..a.len() {
            b[i + size] = a[i].clone();
        }
        let mut seg = SegmentTreePURQ { seg: b, size: size };
        seg.update_all();
        seg
    }
    fn update(&mut self, x: usize, v: R::T) {
        assert!(x < self.size);
        let mut x = x + self.size;
        let a = &mut self.seg;
        a[x] = v;
        x >>= 1;
        while x > 0 {
            a[x] = R::fold(&a[2 * x], &a[2 * x + 1]);
            x >>= 1;
        }
    }
    fn update_tmp(&mut self, x: usize, v: R::T) {
        self.seg[self.size + x] = v;
    }
    fn update_all(&mut self) {
        let a = &mut self.seg;
        for i in (1..self.size).rev() {
            a[i] = R::fold(&a[2 * i], &a[2 * i + 1]);
        }
    }
    fn find(&self, l: usize, r: usize) -> R::T {
        assert!(l <= r && r <= self.size);
        let mut x = R::e();
        let mut y = R::e();
        let mut l = l + self.size;
        let mut r = r + self.size;
        let a = &self.seg;
        while l < r {
            if l & 1 == 1 {
                x = R::fold(&x, &a[l]);
                l += 1;
            }
            if r & 1 == 1 {
                r -= 1;
                y = R::fold(&a[r], &y);
            }
            l >>= 1;
            r >>= 1;
        }
        R::fold(&x, &y)
    }
    // f(a[l..k]) がkについてfalse, false, ..., true みたいに単調であるとした時
    // 戻り値Some(x)は
    // f(&a[l..x]) = false
    // f(&a[l..=x]) = true
    // を満たす
    fn search_right<F>(&self, l: usize, f: F) -> Option<usize>
    where
        F: Fn(&R::T) -> bool,
    {
        let a = &self.seg;
        let mut v = R::e();
        let mut r = self.size * 2;
        let mut l = l + self.size;
        while l < r {
            if l & 1 == 1 {
                let u = R::fold(&v, &a[l]);
                if f(&u) {
                    break;
                }
                l += 1;
                v = u;
            }
            l >>= 1;
            r >>= 1;
        }
        if l == r {
            return None;
        }
        let mut x = l;
        while x < self.size {
            x <<= 1;
            let u = R::fold(&v, &a[x]);
            if !f(&u) {
                x += 1;
                v = u;
            }
        }
        Some(x - self.size)
    }
}
//---------- end SegmentTree Point update Range query ----------

