struct RMQ;
impl PURQ for RMQ {
    type T = i32;
    fn fold(l: &Self::T, r: &Self::T) -> Self::T {
        std::cmp::max(*l, *r)
    }
    fn e() -> Self::T {
        -1
    }
}

#[fastout]
fn run() {
    input! {
        n: usize,
        q: usize,
        a: [i32; n],
        ask: [(u8, Usize1, i32); q],
    }
    let mut seg = SegmentTreePURQ::<RMQ>::build_by(&a);
    for (op, a, b) in ask {
        if op == 1 {
            let x = a;
            let v = b;
            seg.update(x, v);
        } else if op == 2 {
            let l = a;
            let r = b as usize;
            let ans = seg.find(l, r);
            println!("{}", ans);
        } else {
            let x = a;
            let v = b;
            let k = seg.search_right(x, |p| *p >= v);
            if let Some(k) = k {
                println!("{}", k + 1);
            } else {
                println!("{}", n + 1);
            }
        }
    }
}

